    #[test]
    fn first_occurrence_of_is_some_iff_occurs_in_across_every_target_and_triple() {
        // PRESENCE-COMPOSITION IDENTITY: for every slice `items` and
        // every target `v`,
        // `T::first_occurrence_of(v, items).is_some() == T::occurs_in(v, items)`
        // — the Option discriminant is the per-target bool membership
        // predicate. Sweeps the full 3×27 = 81-corner (target ×
        // triple) matrix. Catches an override that detaches the
        // Option discriminant from the strictly-positive fixpoint of
        // the per-target multiplicity primitive.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let via_option =
                            <StubKind as ClosedSet>::first_occurrence_of(v, &triple).is_some();
                        let via_bool = <StubKind as ClosedSet>::occurs_in(v, &triple);
                        assert_eq!(
                            via_option, via_bool,
                            "T::first_occurrence_of({v:?}, {triple:?}).is_some() diverged from T::occurs_in({v:?}, {triple:?})",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn first_occurrence_of_is_the_smallest_matching_position_across_every_target_and_triple() {
        // SMALLEST-POSITION CONTRACT: at every valid index
        // `i < T::first_occurrence_of(v, items).unwrap_or(items.len())`,
        // `T::index_of(items[i]) != T::index_of(v)` — every position
        // strictly BEFORE the returned head-position is a miss. Sweeps
        // the full 3×27 = 81-corner (target × triple) matrix.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let head = <StubKind as ClosedSet>::first_occurrence_of(v, &triple);
                        let bound = head.unwrap_or(triple.len());
                        for i in 0..bound {
                            assert_ne!(
                                <StubKind as ClosedSet>::index_of(triple[i]),
                                <StubKind as ClosedSet>::index_of(v),
                                "T::first_occurrence_of({v:?}, {triple:?}) = {head:?} but slot {i} at {slot:?} MATCHES target — head-position projection was not the SMALLEST matching slot",
                                slot = triple[i],
                            );
                        }
                        if let Some(head_index) = head {
                            assert_eq!(
                                <StubKind as ClosedSet>::index_of(triple[head_index]),
                                <StubKind as ClosedSet>::index_of(v),
                                "T::first_occurrence_of({v:?}, {triple:?}) = Some({head_index}) but slot {head_index} at {slot:?} does NOT match target",
                                slot = triple[head_index],
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn first_occurrence_of_returns_valid_slice_index_when_some_across_every_target_and_triple() {
        // UPPER-BOUND CONTRACT: `T::first_occurrence_of(v, items) ==
        // Some(i)` implies `i < items.len()` — a `Some(_)` position is
        // a valid slice index in `[0, items.len())`.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        if let Some(head) = <StubKind as ClosedSet>::first_occurrence_of(v, &triple)
                        {
                            assert!(
                                head < triple.len(),
                                "T::first_occurrence_of({v:?}, {triple:?}) = Some({head}) out of slice bounds ({len})",
                                len = triple.len(),
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn last_occurrence_of_returns_none_on_the_empty_slice_across_every_target() {
        // EMPTY-SLICE CONTRACT: `T::last_occurrence_of(v, &[])` is
        // `None` for every target `v`.
        let empty: &[StubKind] = &[];
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            assert_eq!(
                <StubKind as ClosedSet>::last_occurrence_of(v, empty),
                None,
                "T::last_occurrence_of({v:?}, &[]) diverged from the empty-slice fixpoint None",
            );
        }
    }

    #[test]
    fn last_occurrence_of_returns_some_zero_on_the_matching_singleton_across_every_target() {
        // MATCHING-SINGLETON CONTRACT:
        // `T::last_occurrence_of(v, &[v]) == Some(0)` — a singleton
        // slice has first == last at index 0.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert_eq!(
                <StubKind as ClosedSet>::last_occurrence_of(v, &singleton),
                Some(0),
                "T::last_occurrence_of({v:?}, {singleton:?}) diverged from Some(0)",
            );
        }
    }

    #[test]
    fn last_occurrence_of_returns_some_index_of_on_the_full_set_across_every_target() {
        // FULL-SET CONTRACT:
        // `T::last_occurrence_of(v, T::ALL) == Some(T::index_of(v))`
        // — clause (3)'s pairwise-distinctness invariant forces every
        // variant to appear at exactly ONE position of T::ALL, so
        // first and last coincide at the variant's decl-slot.
        let all = <StubKind as ClosedSet>::ALL;
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let expected = Some(<StubKind as ClosedSet>::index_of(v));
            assert_eq!(
                <StubKind as ClosedSet>::last_occurrence_of(v, all),
                expected,
                "T::last_occurrence_of({v:?}, T::ALL) diverged from Some(T::index_of({v:?}))",
            );
        }
    }

    #[test]
    fn last_occurrence_of_returns_second_hit_on_the_doubled_full_set_across_every_target() {
        // DOUBLED-FULL-SET CONTRACT:
        // `T::last_occurrence_of(v, T::ALL ++ T::ALL) == Some(T::CARDINALITY + T::index_of(v))`
        // — each variant appears at TWO positions
        // (`T::index_of(v)` and `T::CARDINALITY + T::index_of(v)`),
        // and the tail-position projection binds the SECOND
        // occurrence. This catches an endpoint-direction swap
        // undetectable on the full set alone.
        let doubled: Vec<StubKind> = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .chain(<StubKind as ClosedSet>::ALL.iter().copied())
            .collect();
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let expected =
                Some(<StubKind as ClosedSet>::CARDINALITY + <StubKind as ClosedSet>::index_of(v));
            assert_eq!(
                <StubKind as ClosedSet>::last_occurrence_of(v, &doubled),
                expected,
                "T::last_occurrence_of({v:?}, ALL++ALL) diverged from Some(CARDINALITY + index_of({v:?}))",
            );
        }
    }

    #[test]
    fn last_occurrence_of_is_some_iff_occurs_in_across_every_target_and_triple() {
        // PRESENCE-COMPOSITION IDENTITY: for every slice `items` and
        // every target `v`,
        // `T::last_occurrence_of(v, items).is_some() == T::occurs_in(v, items)`.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let via_option =
                            <StubKind as ClosedSet>::last_occurrence_of(v, &triple).is_some();
                        let via_bool = <StubKind as ClosedSet>::occurs_in(v, &triple);
                        assert_eq!(
                            via_option, via_bool,
                            "T::last_occurrence_of({v:?}, {triple:?}).is_some() diverged from T::occurs_in({v:?}, {triple:?})",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn last_occurrence_of_is_the_largest_matching_position_across_every_target_and_triple() {
        // LARGEST-POSITION CONTRACT: at every valid index
        // `i > T::last_occurrence_of(v, items).unwrap_or(0)` (when
        // Some) and every valid index `i < items.len()` (when None),
        // `T::index_of(items[i]) != T::index_of(v)` — every position
        // strictly AFTER the returned tail-position is a miss.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let tail = <StubKind as ClosedSet>::last_occurrence_of(v, &triple);
                        match tail {
                            None => {
                                for i in 0..triple.len() {
                                    assert_ne!(
                                        <StubKind as ClosedSet>::index_of(triple[i]),
                                        <StubKind as ClosedSet>::index_of(v),
                                        "T::last_occurrence_of({v:?}, {triple:?}) = None but slot {i} at {slot:?} MATCHES",
                                        slot = triple[i],
                                    );
                                }
                            }
                            Some(tail_index) => {
                                assert_eq!(
                                    <StubKind as ClosedSet>::index_of(triple[tail_index]),
                                    <StubKind as ClosedSet>::index_of(v),
                                    "T::last_occurrence_of({v:?}, {triple:?}) = Some({tail_index}) but slot {tail_index} at {slot:?} does NOT match",
                                    slot = triple[tail_index],
                                );
                                for i in (tail_index + 1)..triple.len() {
                                    assert_ne!(
                                        <StubKind as ClosedSet>::index_of(triple[i]),
                                        <StubKind as ClosedSet>::index_of(v),
                                        "T::last_occurrence_of({v:?}, {triple:?}) = Some({tail_index}) but slot {i} > tail at {slot:?} MATCHES target — tail-position projection was not the LARGEST matching slot",
                                        slot = triple[i],
                                    );
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn first_occurrence_of_is_at_most_last_occurrence_of_across_every_target_and_triple() {
        // ORDERING-VS-LAST CONTRACT:
        // `T::first_occurrence_of(v, items) <= T::last_occurrence_of(v, items)`
        // under the product `Option<usize>` order (both `None` when
        // absent; both `Some` with `first <= last` when present).
        // Bridges the head and tail arms of the (per-target ×
        // Option<usize> × endpoint-direction) 2-corner face.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let head = <StubKind as ClosedSet>::first_occurrence_of(v, &triple);
                        let tail = <StubKind as ClosedSet>::last_occurrence_of(v, &triple);
                        assert_eq!(
                            head.is_some(),
                            tail.is_some(),
                            "T::first_occurrence_of({v:?}, {triple:?}) = {head:?} and T::last_occurrence_of = {tail:?} disagree on Option discriminant",
                        );
                        if let (Some(h), Some(t)) = (head, tail) {
                            assert!(
                                h <= t,
                                "T::first_occurrence_of({v:?}, {triple:?}) = Some({h}) > T::last_occurrence_of = Some({t}) — head-tail ordering violated",
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn slice_reversal_swaps_first_and_last_occurrence_of_across_every_target_and_triple() {
        // SLICE-REVERSAL CONTRACT: for every slice `items` and every
        // target `v` with `T::last_occurrence_of(v, items) == Some(j)`,
        // `T::first_occurrence_of(v, &reversed(items)) == Some(items.len() - 1 - j)`.
        // Reversing the slice swaps first and last positions modulo
        // `items.len() - 1`. Bridges the head arm on the reversed
        // slice to the tail arm on the forward slice, closing the
        // endpoint-direction axis under slice reversal.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let forward = [a, b, c];
                    let reversed = [c, b, a];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let tail_forward = <StubKind as ClosedSet>::last_occurrence_of(v, &forward);
                        let head_reversed =
                            <StubKind as ClosedSet>::first_occurrence_of(v, &reversed);
                        let expected_head_reversed = tail_forward.map(|j| forward.len() - 1 - j);
                        assert_eq!(
                            head_reversed, expected_head_reversed,
                            "T::first_occurrence_of({v:?}, reversed({forward:?})) = {head_reversed:?} diverged from expected {expected_head_reversed:?} = map(last_occurrence_of({v:?}, {forward:?}) = {tail_forward:?}, |j| len - 1 - j)",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn assert_closed_set_well_formed_catches_drift_between_first_occurrence_of_and_full_set() {
        // Drift catch — clause (106)'s full-set fixpoint arm fires
        // when an override folds the per-target head-position onto
        // `None` regardless of target. The stub below overrides the
        // default body to return `None` unconditionally; on the full
        // set that produces `None != Some(T::index_of(target))` at
        // every target, tripping clause (106)'s full-set fixpoint arm
        // loudly.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedFirstOccurrenceKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedFirstOccurrenceKind(pub String);

        impl core::fmt::Display for UnknownDriftedFirstOccurrenceKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(f, "unknown drifted first_occurrence kind: {}", self.0)
            }
        }

        impl DriftedFirstOccurrenceKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedFirstOccurrenceKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted first_occurrence kind";
            type Unknown = UnknownDriftedFirstOccurrenceKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedFirstOccurrenceKind(s.to_owned())
            }
            fn first_occurrence_of(_target: Self, _items: &[Self]) -> Option<usize> {
                None
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedFirstOccurrenceKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedFirstOccurrenceKind whose first_occurrence_of override folds onto None unconditionally — clause (106)'s full-set fixpoint arm MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_endpoint_direction_swap_on_last_occurrence_of() {
        // Drift catch — clause (107)'s doubled-full-set arm fires when
        // an override swaps the endpoint direction (returns the FIRST
        // hit instead of the LAST). The stub below overrides the
        // default body to delegate to `first_occurrence_of`; on the
        // doubled full set at every target with `T::index_of(target) >
        // 0` (which holds for at least Beta and Gamma), the first hit
        // is at `T::index_of(target)` but the pinned last hit is at
        // `T::CARDINALITY + T::index_of(target) = 3 + T::index_of(target)`,
        // which differs.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedLastOccurrenceKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedLastOccurrenceKind(pub String);

        impl core::fmt::Display for UnknownDriftedLastOccurrenceKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(f, "unknown drifted last_occurrence kind: {}", self.0)
            }
        }

        impl DriftedLastOccurrenceKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedLastOccurrenceKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted last_occurrence kind";
            type Unknown = UnknownDriftedLastOccurrenceKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedLastOccurrenceKind(s.to_owned())
            }
            fn last_occurrence_of(target: Self, items: &[Self]) -> Option<usize> {
                // Drift: swap endpoint direction — return the FIRST
                // hit rather than the LAST. Clause (107)'s doubled-
                // full-set arm at Beta / Gamma catches the swap
                // because first == index_of(target) but the pinned
                // last == CARDINALITY + index_of(target).
                let target_index = <Self as ClosedSet>::index_of(target);
                items
                    .iter()
                    .position(|&v| <Self as ClosedSet>::index_of(v) == target_index)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedLastOccurrenceKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedLastOccurrenceKind whose last_occurrence_of override swaps endpoint direction — clause (107)'s doubled-full-set arm MUST reject the drift",
        );
    }

    #[test]
    fn all_occurrences_of_returns_empty_on_the_empty_slice_across_every_target() {
        // EMPTY-SLICE CONTRACT: `T::all_occurrences_of(v, &[])` is
        // the empty vec at every target — the empty slice hits zero
        // positions, so `enumerate().filter().map()` yields no index.
        let empty: &[StubKind] = &[];
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let positions = <StubKind as ClosedSet>::all_occurrences_of(v, empty);
            assert!(
                positions.is_empty(),
                "T::all_occurrences_of({v:?}, &[]) = {positions:?} != vec![]",
            );
        }
    }

    #[test]
    fn all_occurrences_of_returns_zero_singleton_on_the_matching_singleton_across_every_target() {
        // MATCHING-SINGLETON CONTRACT:
        // `T::all_occurrences_of(v, &[v]) == vec![0]` — the sole
        // position hits the target at slot 0.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let positions = <StubKind as ClosedSet>::all_occurrences_of(v, &[v]);
            assert_eq!(
                positions,
                vec![0],
                "T::all_occurrences_of({v:?}, &[{v:?}]) = {positions:?} != vec![0]",
            );
        }
    }

    #[test]
    fn all_occurrences_of_returns_empty_on_the_non_matching_singleton_across_every_target_pair() {
        // NON-MATCHING-SINGLETON CONTRACT:
        // `T::all_occurrences_of(v, &[w]) == vec![]` for every
        // target `v` and slice-element `w != v` (compared via
        // T::index_of).
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            for w in <StubKind as ClosedSet>::ALL.iter().copied() {
                if <StubKind as ClosedSet>::index_of(v) != <StubKind as ClosedSet>::index_of(w) {
                    let positions = <StubKind as ClosedSet>::all_occurrences_of(v, &[w]);
                    assert!(
                        positions.is_empty(),
                        "T::all_occurrences_of({v:?}, &[{w:?}]) = {positions:?} != vec![]",
                    );
                }
            }
        }
    }

    #[test]
    fn all_occurrences_of_returns_index_of_singleton_on_the_full_set_across_every_target() {
        // FULL-SET CONTRACT:
        // `T::all_occurrences_of(v, <T as ClosedSet>::ALL) == vec![T::index_of(v)]`
        // UNCONDITIONALLY — clause (3)'s pairwise-distinctness invariant
        // forces every variant to appear at exactly ONE position of
        // the full-set slice, at slot `T::index_of(v)`.
        let all = <StubKind as ClosedSet>::ALL;
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let positions = <StubKind as ClosedSet>::all_occurrences_of(v, all);
            let expected = vec![<StubKind as ClosedSet>::index_of(v)];
            assert_eq!(
                positions, expected,
                "T::all_occurrences_of({v:?}, T::ALL) = {positions:?} != {expected:?}",
            );
        }
    }

    #[test]
    fn all_occurrences_of_returns_both_hits_on_the_doubled_full_set_across_every_target() {
        // DOUBLED-FULL-SET CONTRACT:
        // `T::all_occurrences_of(v, &doubled_full_set) == vec![
        //   T::index_of(v),
        //   T::CARDINALITY + T::index_of(v),
        // ]` UNCONDITIONALLY — each variant appears at EXACTLY TWO
        // positions in the doubled slice, and the ascending-order
        // contract pins the head hit at the first-copy slot and the
        // tail hit at the second-copy slot.
        let doubled: Vec<StubKind> = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .chain(<StubKind as ClosedSet>::ALL.iter().copied())
            .collect();
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let positions = <StubKind as ClosedSet>::all_occurrences_of(v, &doubled);
            let idx = <StubKind as ClosedSet>::index_of(v);
            let expected = vec![idx, <StubKind as ClosedSet>::CARDINALITY + idx];
            assert_eq!(
                positions, expected,
                "T::all_occurrences_of({v:?}, doubled_full_set) = {positions:?} != {expected:?}",
            );
        }
    }

    #[test]
    fn all_occurrences_of_len_equals_count_occurrences_of_across_every_target_and_triple() {
        // LENGTH-COMPOSITION IDENTITY:
        // `T::all_occurrences_of(v, items).len() == T::count_occurrences_of(v, items)`
        // on every (v, items) pair — the vec's length is exactly the
        // per-target multiplicity.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let vec_len = <StubKind as ClosedSet>::all_occurrences_of(v, &triple).len();
                        let mult = <StubKind as ClosedSet>::count_occurrences_of(v, &triple);
                        assert_eq!(
                            vec_len, mult,
                            "T::all_occurrences_of({v:?}, {triple:?}).len() = {vec_len} diverged from T::count_occurrences_of({v:?}, {triple:?}) = {mult}",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn all_occurrences_of_first_equals_first_occurrence_of_across_every_target_and_triple() {
        // HEAD-COMPOSITION IDENTITY:
        // `T::all_occurrences_of(v, items).first().copied() == T::first_occurrence_of(v, items)`
        // on every (v, items) pair — the vec's head element is
        // exactly the head-endpoint projection.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let head = <StubKind as ClosedSet>::all_occurrences_of(v, &triple)
                            .first()
                            .copied();
                        let expected = <StubKind as ClosedSet>::first_occurrence_of(v, &triple);
                        assert_eq!(
                            head, expected,
                            "T::all_occurrences_of({v:?}, {triple:?}).first().copied() = {head:?} diverged from T::first_occurrence_of = {expected:?}",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn all_occurrences_of_last_equals_last_occurrence_of_across_every_target_and_triple() {
        // TAIL-COMPOSITION IDENTITY:
        // `T::all_occurrences_of(v, items).last().copied() == T::last_occurrence_of(v, items)`
        // on every (v, items) pair — the vec's tail element is
        // exactly the tail-endpoint projection.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let tail = <StubKind as ClosedSet>::all_occurrences_of(v, &triple)
                            .last()
                            .copied();
                        let expected = <StubKind as ClosedSet>::last_occurrence_of(v, &triple);
                        assert_eq!(
                            tail, expected,
                            "T::all_occurrences_of({v:?}, {triple:?}).last().copied() = {tail:?} diverged from T::last_occurrence_of = {expected:?}",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn all_occurrences_of_is_strictly_increasing_across_every_target_and_triple() {
        // STRICTLY-INCREASING CONTRACT: adjacent elements of
        // `T::all_occurrences_of(v, items)` are strictly
        // increasing — the enumerate-based slice-position ordering
        // pins ascending order and no duplicate index survives the
        // filter's per-position gating.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let positions = <StubKind as ClosedSet>::all_occurrences_of(v, &triple);
                        for window in positions.windows(2) {
                            assert!(
                                window[0] < window[1],
                                "T::all_occurrences_of({v:?}, {triple:?}) = {positions:?} — adjacent slice indices {} and {} are not strictly increasing",
                                window[0],
                                window[1],
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn all_occurrences_of_positions_all_match_across_every_target_and_triple() {
        // POSITIONAL-CORRECTNESS CONTRACT: every returned index `i`
        // satisfies `i < items.len()` AND
        // `T::index_of(items[i]) == T::index_of(v)` — every returned
        // index is a valid slice index at which `items` carries the
        // target's variant identity.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let positions = <StubKind as ClosedSet>::all_occurrences_of(v, &triple);
                        for &i in &positions {
                            assert!(
                                i < triple.len(),
                                "T::all_occurrences_of({v:?}, {triple:?}) = {positions:?} — returned index {i} is out of bounds for len {}",
                                triple.len(),
                            );
                            assert_eq!(
                                <StubKind as ClosedSet>::index_of(triple[i]),
                                <StubKind as ClosedSet>::index_of(v),
                                "T::all_occurrences_of({v:?}, {triple:?}) = {positions:?} — returned index {i} points at {:?} whose decl-slot differs from {v:?}'s",
                                triple[i],
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn all_occurrences_of_summed_over_all_targets_equals_slice_length_across_every_triple() {
        // PARTITION IDENTITY:
        // `T::ALL.iter().map(|v| T::all_occurrences_of(v, items).len()).sum::<usize>()
        //   == items.len()`
        // — the per-target index sets partition the slice's positions
        // exactly (every position sits at EXACTLY ONE variant by the
        // (variant → decl-slot) injectivity clause (16)).
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let sum: usize = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .map(|v| <StubKind as ClosedSet>::all_occurrences_of(v, &triple).len())
                        .sum();
                    assert_eq!(
                        sum,
                        triple.len(),
                        "sum over targets of T::all_occurrences_of(v, {triple:?}).len() = {sum} diverged from triple.len() = {} — the per-target index-set partition identity was violated",
                        triple.len(),
                    );
                }
            }
        }
    }

    #[test]
    fn assert_closed_set_well_formed_catches_drift_between_all_occurrences_of_and_full_set() {
        // Drift catch — clause (108)'s full-set fixpoint arm fires
        // when an override folds the per-target every-position
        // projection onto the empty vec regardless of target. The
        // stub below overrides the default body to return `vec![]`
        // unconditionally; on the full set that produces
        // `vec![] != vec![T::index_of(target)]` at every target,
        // tripping clause (108)'s full-set fixpoint arm loudly.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedAllOccurrencesEmptyKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedAllOccurrencesEmptyKind(pub String);

        impl core::fmt::Display for UnknownDriftedAllOccurrencesEmptyKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(f, "unknown drifted all_occurrences empty kind: {}", self.0)
            }
        }

        impl DriftedAllOccurrencesEmptyKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedAllOccurrencesEmptyKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted all_occurrences empty kind";
            type Unknown = UnknownDriftedAllOccurrencesEmptyKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedAllOccurrencesEmptyKind(s.to_owned())
            }
            fn all_occurrences_of(_target: Self, _items: &[Self]) -> ::std::vec::Vec<usize> {
                ::std::vec::Vec::new()
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedAllOccurrencesEmptyKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedAllOccurrencesEmptyKind whose all_occurrences_of override folds onto vec![] unconditionally — clause (108)'s full-set fixpoint arm MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_length_drift_on_all_occurrences_of() {
        // Drift catch — clause (108)'s doubled-full-set arm fires
        // when an override drops the tail hit and returns only the
        // head singleton `vec![T::index_of(target)]` regardless of
        // slice arity. On the doubled full set that returns a
        // length-1 vec instead of the pinned length-2
        // `vec![T::index_of(target), T::CARDINALITY + T::index_of(target)]`,
        // tripping the doubled-full-set arm loudly and simultaneously
        // bifurcating the tail-composition arm against
        // `T::last_occurrence_of`.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedAllOccurrencesHeadOnlyKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedAllOccurrencesHeadOnlyKind(pub String);

        impl core::fmt::Display for UnknownDriftedAllOccurrencesHeadOnlyKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted all_occurrences head-only kind: {}",
                    self.0
                )
            }
        }

        impl DriftedAllOccurrencesHeadOnlyKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedAllOccurrencesHeadOnlyKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted all_occurrences head-only kind";
            type Unknown = UnknownDriftedAllOccurrencesHeadOnlyKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedAllOccurrencesHeadOnlyKind(s.to_owned())
            }
            fn all_occurrences_of(target: Self, _items: &[Self]) -> ::std::vec::Vec<usize> {
                // Drift: drop the tail hit — always return only the
                // head-anchor singleton. On the doubled full set that
                // returns `vec![T::index_of(target)]` instead of the
                // pinned length-2 vec, bifurcating clause (108)'s
                // doubled-full-set arm.
                vec![<Self as ClosedSet>::index_of(target)]
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedAllOccurrencesHeadOnlyKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedAllOccurrencesHeadOnlyKind whose all_occurrences_of override drops the tail hit — clause (108)'s doubled-full-set arm MUST reject the drift",
        );
    }

    #[test]
    fn occurrence_endpoints_of_returns_none_on_the_empty_slice_across_every_target() {
        // EMPTY-SLICE CONTRACT (per-target × Option<(usize, usize)>
        // endpoint-pair projection): `T::occurrence_endpoints_of(v,
        // &[])` is `None` for every target `v` — both endpoint-anchor
        // primitives yield `None` on the zero-position slice, and
        // `Option::zip` collapses to `None` iff EITHER input is
        // `None`. Sibling posture to
        // `first_occurrence_of_returns_none_on_the_empty_slice_across_every_target`
        // + `last_occurrence_of_returns_none_on_the_empty_slice_across_every_target`
        // on the endpoint-anchor pair: this pair-lift projects the
        // same `None` empty-slice fixpoint through `Option::zip`.
        let empty: &[StubKind] = &[];
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            assert_eq!(
                <StubKind as ClosedSet>::occurrence_endpoints_of(v, empty),
                None,
                "T::occurrence_endpoints_of({v:?}, &[]) diverged from the empty-slice fixpoint `None`",
            );
        }
    }

    #[test]
    fn occurrence_endpoints_of_returns_some_zero_zero_on_the_matching_singleton_across_every_target(
    ) {
        // MATCHING-SINGLETON CONTRACT: `T::occurrence_endpoints_of(v,
        // &[v]) == Some((0, 0))` for every target `v` — the sole
        // position hits the target, so both endpoint-anchor primitives
        // yield `Some(0)` and `Option::zip` packages the pair as
        // `Some((0, 0))`. The two components coincide because on a
        // singleton the head and tail hit are the same slot.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert_eq!(
                <StubKind as ClosedSet>::occurrence_endpoints_of(v, &singleton),
                Some((0, 0)),
                "T::occurrence_endpoints_of({v:?}, {singleton:?}) diverged from the matching-singleton fixpoint `Some((0, 0))`",
            );
        }
    }

    #[test]
    fn occurrence_endpoints_of_returns_none_on_the_non_matching_singleton_across_every_target_pair()
    {
        // NON-MATCHING-SINGLETON CONTRACT:
        // `T::occurrence_endpoints_of(v, &[w]) == None` for every
        // target `v` and slice-element `w` with `T::index_of(v) !=
        // T::index_of(w)` — both endpoint-anchor primitives miss on a
        // singleton at a different variant, and `Option::zip`
        // collapses to `None`. Sweeps every (target, singleton-
        // element) pair pins the miss contract across the full 3×3 =
        // 9-corner matrix at the six OFF-DIAGONAL corners.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            for w in <StubKind as ClosedSet>::ALL.iter().copied() {
                if <StubKind as ClosedSet>::index_of(v) != <StubKind as ClosedSet>::index_of(w) {
                    let singleton = [w];
                    assert_eq!(
                        <StubKind as ClosedSet>::occurrence_endpoints_of(v, &singleton),
                        None,
                        "T::occurrence_endpoints_of({v:?}, {singleton:?}) diverged from the non-matching-singleton fixpoint `None`",
                    );
                }
            }
        }
    }

    #[test]
    fn occurrence_endpoints_of_returns_index_of_pair_on_the_full_set_across_every_target() {
        // FULL-SET CONTRACT:
        // `T::occurrence_endpoints_of(v, T::ALL) ==
        // Some((T::index_of(v), T::index_of(v)))` UNCONDITIONALLY —
        // clause (3)'s pairwise-distinctness invariant forces every
        // variant to appear at exactly ONE position of the full-set
        // slice, so both endpoint-anchor primitives yield
        // `Some(T::index_of(v))` and `Option::zip` packages the pair
        // with coincident components. The two components coincide
        // BECAUSE the full-set slice hits each variant exactly once
        // (head-position == tail-position on singleton-hit slices).
        let all = <StubKind as ClosedSet>::ALL;
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let expected = <StubKind as ClosedSet>::index_of(v);
            assert_eq!(
                <StubKind as ClosedSet>::occurrence_endpoints_of(v, all),
                Some((expected, expected)),
                "T::occurrence_endpoints_of({v:?}, T::ALL) diverged from Some((T::index_of({v:?}), T::index_of({v:?}))) — the closed-set well-formedness pairwise-distinctness invariant would be violated",
            );
        }
    }

    #[test]
    fn occurrence_endpoints_of_returns_head_tail_pair_on_the_doubled_full_set_across_every_target()
    {
        // DOUBLED-FULL-SET CONTRACT:
        // `T::occurrence_endpoints_of(v, T::ALL ++ T::ALL) ==
        // Some((T::index_of(v), T::CARDINALITY + T::index_of(v)))`
        // UNCONDITIONALLY — the doubled full set hits every variant
        // at exactly TWO positions spanning the two copies. The
        // doubled-slice arm is the ONLY canonical fixpoint arm that
        // separates the (head, tail) direction axis (on the full set
        // alone the two coincide), catching an override that swaps
        // the pair components or drops one of them.
        let doubled: Vec<StubKind> = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .chain(<StubKind as ClosedSet>::ALL.iter().copied())
            .collect();
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let head = <StubKind as ClosedSet>::index_of(v);
            let tail = <StubKind as ClosedSet>::CARDINALITY + head;
            assert_eq!(
                <StubKind as ClosedSet>::occurrence_endpoints_of(v, &doubled),
                Some((head, tail)),
                "T::occurrence_endpoints_of({v:?}, ALL++ALL) diverged from Some((T::index_of({v:?}), T::CARDINALITY + T::index_of({v:?}))) — the doubled-slice fixpoint pins the (head, tail) pair to span the two copies",
            );
        }
    }

    #[test]
    fn occurrence_endpoints_of_is_some_iff_occurs_in_across_every_target_and_triple() {
        // PRESENCE-COMPOSITION IDENTITY: for every slice `items` and
        // every target `v`,
        // `T::occurrence_endpoints_of(v, items).is_some() ==
        // T::occurs_in(v, items)` — the `Option`'s discriminant is
        // exactly the per-target bool membership predicate. Sweeping
        // every length-3 triple × every target pins the identity
        // across the full 3×27 = 81-corner (target × triple) matrix.
        // Sibling posture to
        // `first_occurrence_of_is_some_iff_occurs_in_across_every_target_and_triple`
        // on the endpoint-anchor pair.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let via_pair =
                            <StubKind as ClosedSet>::occurrence_endpoints_of(v, &triple).is_some();
                        let via_bool = <StubKind as ClosedSet>::occurs_in(v, &triple);
                        assert_eq!(
                            via_pair, via_bool,
                            "T::occurrence_endpoints_of({v:?}, {triple:?}).is_some() diverged from T::occurs_in({v:?}, {triple:?}) — the pair's `Some` arm MUST coincide with the bool membership predicate",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn occurrence_endpoints_of_equals_zip_of_first_and_last_occurrence_of_across_every_target_and_triple(
    ) {
        // ENDPOINT-PAIR COMPOSITION IDENTITY: for every slice `items`
        // and every target `v`,
        // `T::occurrence_endpoints_of(v, items) ==
        // T::first_occurrence_of(v, items).zip(T::last_occurrence_of(v, items))`
        // — the pair-return is the direct `Option::zip` of the two
        // endpoint-anchor projections. Sweeping every length-3 triple
        // × every target pins the identity across the full 3×27 =
        // 81-corner (target × triple) matrix. Catches a future
        // override that detaches the pair projection from the
        // endpoint-anchor pair on any slice.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let via_pair = <StubKind as ClosedSet>::occurrence_endpoints_of(v, &triple);
                        let via_zip = <StubKind as ClosedSet>::first_occurrence_of(v, &triple)
                            .zip(<StubKind as ClosedSet>::last_occurrence_of(v, &triple));
                        assert_eq!(
                            via_pair, via_zip,
                            "T::occurrence_endpoints_of({v:?}, {triple:?}) diverged from T::first_occurrence_of({v:?}, {triple:?}).zip(T::last_occurrence_of({v:?}, {triple:?})) — the pair projection MUST equal the direct `Option::zip` of the two endpoint-anchor projections",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn occurrence_endpoints_of_head_equals_first_occurrence_of_across_every_target_and_triple() {
        // HEAD-PROJECTION IDENTITY:
        // `T::occurrence_endpoints_of(v, items).map(|(f, _)| f) ==
        // T::first_occurrence_of(v, items)` — the first component of
        // the pair equals the head-endpoint. Catches an override that
        // stores the head in the second slot (a pair-swap) — on the
        // singleton-hit full set both components coincide so the swap
        // is invisible; the doubled-full-set sweep here catches it on
        // the 3-corner variant sub-face.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    for v in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let head_via_pair =
                            <StubKind as ClosedSet>::occurrence_endpoints_of(v, &triple)
                                .map(|(f, _)| f);
                        let head_direct = <StubKind as ClosedSet>::first_occurrence_of(v, &triple);
                        assert_eq!(
                            head_via_pair, head_direct,
                            "T::occurrence_endpoints_of({v:?}, {triple:?}).map(|(f,_)|f) diverged from T::first_occurrence_of({v:?}, {triple:?}) — the head-projection arm bifurcated",
                        );
                    }
                }
            }
        }
    }

