    #[test]
    fn count_antimodal_variants_can_exceed_count_distinct_when_missing_any() {
        // ARGMIN-VS-ARGMAX ASYMMETRY: the argmin cardinality CAN exceed
        // the count of PRESENT variants on any slice with a missing
        // variant, because the argmin band contains those missing
        // variants (count == 0 == min) which are NOT counted in
        // `count_distinct`. This is the sole non-degenerate asymmetry
        // between `count_modal_variants` (bounded above by
        // `count_distinct`) and `count_antimodal_variants` (bounded
        // above by `CARDINALITY` alone). Pinned on the matching-
        // singleton at cardinality >= 2 as a witness: `count_distinct
        // == 1` while `count_antimodal_variants == CARDINALITY - 1`, so
        // the inequality flips strictly at CARDINALITY >= 3.
        const {
            assert!(
                <StubKind as ClosedSet>::CARDINALITY >= 3,
                "StubKind cardinality changed — this test assumes >= 3 to demonstrate the strict inequality (count_distinct == 1 < CARDINALITY - 1 == count_antimodal_variants)",
            );
        }
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            let antimodal = <StubKind as ClosedSet>::count_antimodal_variants(&singleton);
            let distinct = <StubKind as ClosedSet>::count_distinct(&singleton);
            assert!(
                antimodal > distinct,
                "T::count_antimodal_variants({singleton:?}) = {antimodal} did NOT exceed T::count_distinct({singleton:?}) = {distinct} — the argmin cardinality contains missing variants (count == 0) which are NOT counted in the distinct cardinality, so at CARDINALITY >= 3 the strict inequality MUST fire",
            );
        }
    }

