    #[test]
    fn assert_closed_set_well_formed_catches_always_zero_drift_in_count_antimodal_variants() {
        // Drift catch — clause (132)'s full-set + doubled-full-set arms
        // fire when an override folds the set-level antimodal-tie count
        // onto `0` unconditionally. On the full set + doubled-full set
        // that produces `0 != T::CARDINALITY`, tripping the flat-
        // histogram fixpoint arms loudly. Sibling posture to the
        // `count_modal_variants` → `0` drift catch one DIRECTION axis
        // over.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedCountAntimodalVariantsZeroKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedCountAntimodalVariantsZeroKind(pub String);

        impl core::fmt::Display for UnknownDriftedCountAntimodalVariantsZeroKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted count_antimodal_variants zero kind: {}",
                    self.0
                )
            }
        }

        impl DriftedCountAntimodalVariantsZeroKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedCountAntimodalVariantsZeroKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted count_antimodal_variants zero kind";
            type Unknown = UnknownDriftedCountAntimodalVariantsZeroKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedCountAntimodalVariantsZeroKind(s.to_owned())
            }
            fn count_antimodal_variants(_items: &[Self]) -> usize {
                // Drift: return `0` regardless of slice. On the full set
                // + doubled-full set that produces `0 != T::CARDINALITY`,
                // tripping clause (132)'s flat-histogram fixpoint arms
                // loudly.
                0
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedCountAntimodalVariantsZeroKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedCountAntimodalVariantsZeroKind whose count_antimodal_variants override folds onto `0` unconditionally — clause (132)'s full-set + doubled-full-set arms MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_cardinality_drift_in_count_antimodal_variants()
    {
        // Drift catch — clause (132)'s empty-slice fixpoint arm fires
        // when an override omits the empty-slice guard and returns
        // `T::CARDINALITY` on `&[]` past the (min == 0, every-count ==
        // 0) degenerate arm where every variant satisfies the vacuous
        // `0 == 0` predicate. Sibling posture to the drift catches for
        // `antimodal_variants` / `sorted_antimodal_variants` empty-
        // slice guard omission one RETURN-SHAPE axis over.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedCountAntimodalVariantsCardinalityKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedCountAntimodalVariantsCardinalityKind(pub String);

        impl core::fmt::Display for UnknownDriftedCountAntimodalVariantsCardinalityKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted count_antimodal_variants cardinality kind: {}",
                    self.0
                )
            }
        }

        impl DriftedCountAntimodalVariantsCardinalityKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedCountAntimodalVariantsCardinalityKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted count_antimodal_variants cardinality kind";
            type Unknown = UnknownDriftedCountAntimodalVariantsCardinalityKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedCountAntimodalVariantsCardinalityKind(s.to_owned())
            }
            fn count_antimodal_variants(items: &[Self]) -> usize {
                // Drift shape: omit the empty-slice guard. Correct on
                // every non-empty slice but BIFURCATES at the empty
                // slice, returning T::CARDINALITY past the (min == 0,
                // every-count == 0) degenerate arm where every variant
                // satisfies the vacuous `0 == 0` predicate. Clause
                // (132)'s empty-slice fixpoint arm fires at
                // `T::CARDINALITY != 0`.
                let min = <Self as ClosedSet>::min_variant_count(items);
                <Self as ClosedSet>::ALL
                    .iter()
                    .copied()
                    .filter(|&v| <Self as ClosedSet>::count_occurrences_of(v, items) == min)
                    .count()
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedCountAntimodalVariantsCardinalityKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedCountAntimodalVariantsCardinalityKind whose count_antimodal_variants override omits the empty-slice guard — clause (132)'s empty-slice fixpoint arm MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_mirror_modal_singleton_drift_in_count_antimodal_variants(
    ) {
        // Drift catch — clause (132)'s matching-singleton at cardinality
        // >= 2 arm fires when an override MIRRORS the argmax singleton
        // fixpoint (`1` on every singleton) onto the argmin corner.
        // The argmax corner is `1` on every singleton (only the target
        // hits `count == max == 1`); the argmin corner is `CARDINALITY -
        // 1` on every singleton at CARDINALITY >= 2 (every non-target
        // hits `count == 0 == min`). An override that mirrors the argmax
        // shape bifurcates loudly at the (argmin × singleton) endpoint
        // separating the direction-axis peers.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedCountAntimodalVariantsMirrorSingletonKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedCountAntimodalVariantsMirrorSingletonKind(pub String);

        impl core::fmt::Display for UnknownDriftedCountAntimodalVariantsMirrorSingletonKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted count_antimodal_variants mirror singleton kind: {}",
                    self.0
                )
            }
        }

        impl DriftedCountAntimodalVariantsMirrorSingletonKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedCountAntimodalVariantsMirrorSingletonKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str =
                "drifted count_antimodal_variants mirror singleton kind";
            type Unknown = UnknownDriftedCountAntimodalVariantsMirrorSingletonKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedCountAntimodalVariantsMirrorSingletonKind(s.to_owned())
            }
            fn count_antimodal_variants(items: &[Self]) -> usize {
                // Drift shape: mirror the argmax singleton fixpoint by
                // filtering on `count == max` instead of `count == min`.
                // Correct on flat-histogram fixpoints (empty, full,
                // doubled-full where max == min) but BIFURCATES on the
                // singleton at CARDINALITY >= 2 where max == 1 (only
                // the target satisfies `count == 1`) but the correct
                // argmin fixpoint has min == 0 (every non-target
                // satisfies `count == 0`). Clause (132)'s singleton arm
                // fires at `1 != CARDINALITY - 1 == 2`.
                if items.is_empty() {
                    return 0;
                }
                let max = <Self as ClosedSet>::max_variant_count(items);
                <Self as ClosedSet>::ALL
                    .iter()
                    .copied()
                    .filter(|&v| <Self as ClosedSet>::count_occurrences_of(v, items) == max)
                    .count()
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedCountAntimodalVariantsMirrorSingletonKind>(
            );
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedCountAntimodalVariantsMirrorSingletonKind whose count_antimodal_variants override mirrors the argmax singleton fixpoint onto the argmin corner — clause (132)'s matching-singleton arm at cardinality >= 2 MUST reject the drift",
        );
    }

