    #[test]
    fn is_unique_modal_variant_of_returns_false_on_the_empty_slice_across_every_target() {
        // EMPTY-SLICE CONTRACT (per-target × bool × statistical-aggregate
        // × direction × argmax × unique-tie sharpening): for every target
        // `v`, `T::is_unique_modal_variant_of(v, &[])` is `false`
        // UNCONDITIONALLY — the empty slice hits zero positions,
        // `T::is_modal_variant_of(v, &[])` collapses to `false` via its
        // empty-slice guard, and the conjunction with `T::has_unique_mode`
        // lands on `false` through the membership arm before the
        // uniqueness arm is consulted. Sibling posture to
        // `is_modal_variant_of_returns_false_on_the_empty_slice_across_every_target`
        // one UNIQUE-TIE-SHARPENING axis over: the unsharpened per-target
        // argmax predicate reports `false` at every target; THIS
        // sharpened predicate inherits the fixpoint verbatim.
        let empty: &[StubKind] = &[];
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            assert!(
                !<StubKind as ClosedSet>::is_unique_modal_variant_of(v, empty),
                "T::is_unique_modal_variant_of({v:?}, &[]) diverged from the empty-slice fixpoint `false`",
            );
        }
    }

    #[test]
    fn is_unique_modal_variant_of_returns_true_on_the_matching_singleton_across_every_variant() {
        // MATCHING-SINGLETON CONTRACT: `T::is_unique_modal_variant_of(v, &[v])`
        // is `true` for every variant `v` — the sole position hits `v`
        // with count `1`, T::is_modal_variant_of(v, [v]) is `true` at
        // count == max == 1, T::has_unique_mode([v]) is `true` at
        // count_modal_variants == 1, and the conjunction lands on `true`.
        // Sibling posture to
        // `has_unique_mode_returns_true_on_every_singleton_across_every_variant`
        // one ARITY axis over: the set-level uniqueness bit reports `true`
        // on the matching singleton; THIS per-target predicate reports
        // `true` at EXACTLY the sole matching target.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert!(
                <StubKind as ClosedSet>::is_unique_modal_variant_of(v, &singleton),
                "T::is_unique_modal_variant_of({v:?}, [{v:?}]) diverged from the matching-singleton fixpoint `true`",
            );
        }
    }

