    #[test]
    fn is_unique_antimodal_variant_of_count_equals_has_unique_antimode_as_usize_across_every_triple(
    ) {
        // AT-MOST-ONE-TARGET IDENTITY: for every slice `items`,
        // `T::ALL.iter().filter(|&v| T::is_unique_antimodal_variant_of(v, items)).count() == usize::from(T::has_unique_antimode(items))`
        // — the set-level filter-count reduction over T::ALL of THIS
        // per-target predicate reports EXACTLY `0` when `items` has no
        // unique antimode and EXACTLY `1` when `items` has a unique
        // antimode. Sibling posture to
        // `is_antimodal_variant_of_count_equals_count_antimodal_variants_across_every_triple`
        // one UNIQUE-TIE-SHARPENING axis over.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let filter_count = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .filter(|&v| {
                            <StubKind as ClosedSet>::is_unique_antimodal_variant_of(v, &triple)
                        })
                        .count();
                    let expected =
                        usize::from(<StubKind as ClosedSet>::has_unique_antimode(&triple));
                    assert_eq!(
                        filter_count, expected,
                        "T::ALL.iter().filter(|v| T::is_unique_antimodal_variant_of(*v, {triple:?})).count() diverged from usize::from(T::has_unique_antimode({triple:?})) — the at-most-one-target identity was violated",
                    );
                }
            }
        }
        // Empty-slice endpoint: no target satisfies, has_unique_antimode
        // is `false`, `false as usize == 0`.
        let empty: &[StubKind] = &[];
        let empty_count = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .filter(|&v| <StubKind as ClosedSet>::is_unique_antimodal_variant_of(v, empty))
            .count();
        assert_eq!(
            empty_count,
            usize::from(<StubKind as ClosedSet>::has_unique_antimode(empty)),
        );
    }

