    #[test]
    fn is_extremal_variant_of_equals_is_modal_or_antimodal_variant_of_across_every_target_and_triple(
    ) {
        // DIRECTION-UNION IDENTITY: for every slice `items` and every
        // target v, T::is_extremal_variant_of(v, items) ==
        // (T::is_modal_variant_of(v, items) ||
        // T::is_antimodal_variant_of(v, items)). The canonical form the
        // body uses.
        for target in <StubKind as ClosedSet>::ALL.iter().copied() {
            for a in <StubKind as ClosedSet>::ALL.iter().copied() {
                for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                    for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let triple = [a, b, c];
                        let via_predicate =
                            <StubKind as ClosedSet>::is_extremal_variant_of(target, &triple);
                        let via_disjunction =
                            <StubKind as ClosedSet>::is_modal_variant_of(target, &triple)
                                || <StubKind as ClosedSet>::is_antimodal_variant_of(
                                    target, &triple,
                                );
                        assert_eq!(
                            via_predicate, via_disjunction,
                            "T::is_extremal_variant_of({target:?}, {triple:?}) diverged from (T::is_modal_variant_of({target:?}, {triple:?}) || T::is_antimodal_variant_of({target:?}, {triple:?})) — the direction-union identity was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn is_extremal_variant_of_holds_iff_count_equals_max_or_min_on_non_empty_across_every_target_and_triple(
    ) {
        // COUNT-BAND IDENTITY: for every NON-EMPTY slice `items` and
        // every target v, T::is_extremal_variant_of(v, items) ==
        // (T::count_occurrences_of(v, items) == T::max_variant_count(items)
        // || T::count_occurrences_of(v, items) == T::min_variant_count(items)).
        for target in <StubKind as ClosedSet>::ALL.iter().copied() {
            for a in <StubKind as ClosedSet>::ALL.iter().copied() {
                for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                    for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let triple = [a, b, c];
                        let via_predicate =
                            <StubKind as ClosedSet>::is_extremal_variant_of(target, &triple);
                        let count = <StubKind as ClosedSet>::count_occurrences_of(target, &triple);
                        let max = <StubKind as ClosedSet>::max_variant_count(&triple);
                        let min = <StubKind as ClosedSet>::min_variant_count(&triple);
                        let via_count_band = count == max || count == min;
                        assert_eq!(
                            via_predicate, via_count_band,
                            "T::is_extremal_variant_of({target:?}, {triple:?}) diverged from (count({target:?}, {triple:?}) == max_variant_count({triple:?}) || count({target:?}, {triple:?}) == min_variant_count({triple:?})) — the count-band identity was violated (count={count}, max={max}, min={min})",
                        );
                    }
                }
            }
        }
    }

