    #[test]
    fn count_extremal_variants_agrees_with_inclusion_exclusion_across_every_triple() {
        // INCLUSION-EXCLUSION IDENTITY: for every slice `items`,
        // `T::count_extremal_variants(items) == T::count_modal_variants(
        // items) + T::count_antimodal_variants(items) -
        // T::count_bimodal_variants(items)` — the sharpening pins the
        // canonical body directly. Under the union-refinement identity
        // T::count_bimodal_variants <= min(count_modal_variants,
        // count_antimodal_variants), so the subtraction never underflows
        // on usize. Sweeping every length-3 triple pins the identity across
        // the full 27-corner (triple) domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_pinned = <StubKind as ClosedSet>::count_extremal_variants(&triple);
                    let modal = <StubKind as ClosedSet>::count_modal_variants(&triple);
                    let antimodal = <StubKind as ClosedSet>::count_antimodal_variants(&triple);
                    let bimodal = <StubKind as ClosedSet>::count_bimodal_variants(&triple);
                    let via_arithmetic = modal + antimodal - bimodal;
                    assert_eq!(
                        via_pinned, via_arithmetic,
                        "T::count_extremal_variants({triple:?}) diverged from the inclusion-exclusion arithmetic count_modal + count_antimodal - count_bimodal = {modal} + {antimodal} - {bimodal} — the sharpened body MUST agree with the arithmetic composition on every slice",
                    );
                }
            }
        }
    }

