    #[test]
    fn is_middle_band_variant_of_holds_iff_count_strictly_between_min_and_max_on_non_empty_across_every_target_and_triple(
    ) {
        // COUNT-BAND STRICT-BETWEEN IDENTITY: for every NON-EMPTY slice
        // `items` and every target v, T::is_middle_band_variant_of(v,
        // items) == (T::min_variant_count(items) <
        // T::count_occurrences_of(v, items) && T::count_occurrences_of(v,
        // items) < T::max_variant_count(items)).
        for target in <StubKind as ClosedSet>::ALL.iter().copied() {
            for a in <StubKind as ClosedSet>::ALL.iter().copied() {
                for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                    for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let triple = [a, b, c];
                        let via_predicate =
                            <StubKind as ClosedSet>::is_middle_band_variant_of(target, &triple);
                        let count = <StubKind as ClosedSet>::count_occurrences_of(target, &triple);
                        let max = <StubKind as ClosedSet>::max_variant_count(&triple);
                        let min = <StubKind as ClosedSet>::min_variant_count(&triple);
                        let via_count_band = min < count && count < max;
                        assert_eq!(
                            via_predicate, via_count_band,
                            "T::is_middle_band_variant_of({target:?}, {triple:?}) diverged from (min_variant_count({triple:?}) < count({target:?}, {triple:?}) && count({target:?}, {triple:?}) < max_variant_count({triple:?})) — the count-band strict-between identity was violated (count={count}, max={max}, min={min})",
                        );
                    }
                }
            }
        }
    }

