    #[test]
    fn is_middle_band_variant_of_partitions_the_variant_surface_with_is_extremal_variant_of_across_every_target_and_triple(
    ) {
        // EXTREME-MIDDLE PARTITION IDENTITY: for every NON-EMPTY slice
        // `items` and every target v, exactly ONE of
        // T::is_extremal_variant_of(v, items) and
        // T::is_middle_band_variant_of(v, items) holds — never both,
        // never neither. On the empty slice BOTH collapse to `false`
        // (the empty slice sits outside the partition entirely).
        for target in <StubKind as ClosedSet>::ALL.iter().copied() {
            let empty: &[StubKind] = &[];
            let extremal_empty = <StubKind as ClosedSet>::is_extremal_variant_of(target, empty);
            let middle_empty = <StubKind as ClosedSet>::is_middle_band_variant_of(target, empty);
            assert!(
                !extremal_empty && !middle_empty,
                "T::is_extremal_variant_of({target:?}, &[]) OR T::is_middle_band_variant_of({target:?}, &[]) reported `true` — the empty slice MUST sit OUTSIDE the (extreme / middle) partition entirely (both `false`)",
            );
            for a in <StubKind as ClosedSet>::ALL.iter().copied() {
                for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                    for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let triple = [a, b, c];
                        let extremal =
                            <StubKind as ClosedSet>::is_extremal_variant_of(target, &triple);
                        let middle =
                            <StubKind as ClosedSet>::is_middle_band_variant_of(target, &triple);
                        assert_ne!(
                            extremal, middle,
                            "T::is_extremal_variant_of({target:?}, {triple:?}) == T::is_middle_band_variant_of({target:?}, {triple:?}) — the (extreme / middle) partition identity was violated on the non-empty slice (both arms coincident at value {extremal})",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn is_middle_band_variant_of_is_invariant_under_slice_reversal_across_every_target_and_triple()
    {
        // REVERSAL INVARIANCE: T::is_middle_band_variant_of(v, items)
        // == T::is_middle_band_variant_of(v,
        // items.iter().rev().copied().collect()). The projection
        // factors through an ordering-agnostic non-empty guard AND the
        // ordering-agnostic T::is_extremal_variant_of predicate.
        for target in <StubKind as ClosedSet>::ALL.iter().copied() {
            for a in <StubKind as ClosedSet>::ALL.iter().copied() {
                for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                    for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                        let triple = [a, b, c];
                        let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                        let via_forward =
                            <StubKind as ClosedSet>::is_middle_band_variant_of(target, &triple);
                        let via_reversed =
                            <StubKind as ClosedSet>::is_middle_band_variant_of(target, &reversed);
                        assert_eq!(
                            via_forward, via_reversed,
                            "T::is_middle_band_variant_of({target:?}, {triple:?}) diverged from T::is_middle_band_variant_of({target:?}, {reversed:?}) — the reversal-invariance contract was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_is_middle_band_variant_of() {
        // Drift catch — clause (145)'s empty-slice + matching-singleton
        // + non-matching-singleton + full-set + doubled-full-set +
        // direction-endpoint fixpoint arms fire when an override folds
        // the per-target strict-middle predicate onto `true`
        // unconditionally.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedIsMiddleBandVariantOfTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedIsMiddleBandVariantOfTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedIsMiddleBandVariantOfTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted is_middle_band_variant_of true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedIsMiddleBandVariantOfTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedIsMiddleBandVariantOfTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted is_middle_band_variant_of true kind";
            type Unknown = UnknownDriftedIsMiddleBandVariantOfTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedIsMiddleBandVariantOfTrueKind(s.to_owned())
            }
            fn is_middle_band_variant_of(_target: Self, _items: &[Self]) -> bool {
                // Drift: return `true` regardless. Fires on the empty-
                // slice arm at every target AND on every non-empty
                // fixpoint at cardinality >= 2 (matching-singleton,
                // non-matching-singleton, full-set, doubled-full-set,
                // both direction-endpoint targets on the bimodal-triple
                // at cardinality >= 3).
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedIsMiddleBandVariantOfTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedIsMiddleBandVariantOfTrueKind whose is_middle_band_variant_of override folds onto `true` unconditionally — clause (145)'s empty-slice + direction-endpoint fixpoint arms MUST reject the drift",
        );
    }

