    fn count_middle_band_variants_returns_zero_on_the_full_set_across_every_kind() {
        // FULL-SET CONTRACT: T::count_middle_band_variants(T::ALL) is `0`
        // UNCONDITIONALLY — clause (3)'s pairwise-distinctness invariant
        // pins every variant at exactly one position, max == min == 1,
        // T::count_extremal_variants reports T::CARDINALITY on the flat-
        // histogram fixpoint, and the arithmetic lands on `0`. Direct
        // instance of the uniformity-collapse identity.
        let all = <StubKind as ClosedSet>::ALL;
        assert_eq!(
            <StubKind as ClosedSet>::count_middle_band_variants(all),
            0,
            "T::count_middle_band_variants(T::ALL) diverged from the full-set fixpoint `0` (there is NO strict-middle inhabitant on any uniform slice)",
        );
    }

