    #[test]
    fn assert_closed_set_well_formed_catches_always_cardinality_drift_in_count_middle_band_variants(
    ) {
        // Drift catch — clause (146)'s empty-slice + full-set + doubled-
        // full-set + matching-singleton + bimodal-triple fixpoint arms
        // fire when an override folds the set-level middle-band
        // cardinality onto `T::CARDINALITY` unconditionally.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedCountMiddleBandVariantsCardinalityKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedCountMiddleBandVariantsCardinalityKind(pub String);

        impl core::fmt::Display for UnknownDriftedCountMiddleBandVariantsCardinalityKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted count_middle_band_variants cardinality kind: {}",
                    self.0
                )
            }
        }

        impl DriftedCountMiddleBandVariantsCardinalityKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedCountMiddleBandVariantsCardinalityKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted count_middle_band_variants cardinality kind";
            type Unknown = UnknownDriftedCountMiddleBandVariantsCardinalityKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedCountMiddleBandVariantsCardinalityKind(s.to_owned())
            }
            fn count_middle_band_variants(_items: &[Self]) -> usize {
                // Drift: return `T::CARDINALITY` regardless. Fires on
                // the empty slice at `T::CARDINALITY != 0` AND on every
                // non-empty fixpoint at `T::CARDINALITY != 0`
                // (matching-singleton, full-set, doubled-full-set) AND
                // on the bimodal-triple at `T::CARDINALITY != 1`.
                <Self as ClosedSet>::CARDINALITY
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedCountMiddleBandVariantsCardinalityKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedCountMiddleBandVariantsCardinalityKind whose count_middle_band_variants override folds onto `T::CARDINALITY` unconditionally — clause (146)'s empty-slice + non-empty fixpoint arms MUST reject the drift",
        );
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_zero_drift_in_count_middle_band_variants() {
        // Drift catch — clause (146)'s bimodal-triple middle-band
        // fixpoint arm fires when an override folds the set-level
        // middle-band cardinality onto `0` unconditionally. On the
        // bimodal-triple that produces `0 != 1` at the sole middle-band
        // fixpoint — WITHOUT this drift catch a `_ => 0` override would
        // silently subsume every empty-slice, uniform, and singleton arm
        // (all landing on `0` naturally) and only bifurcate at the
        // bimodal-triple.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedCountMiddleBandVariantsZeroKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedCountMiddleBandVariantsZeroKind(pub String);

        impl core::fmt::Display for UnknownDriftedCountMiddleBandVariantsZeroKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted count_middle_band_variants zero kind: {}",
                    self.0
                )
            }
        }

        impl DriftedCountMiddleBandVariantsZeroKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedCountMiddleBandVariantsZeroKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted count_middle_band_variants zero kind";
            type Unknown = UnknownDriftedCountMiddleBandVariantsZeroKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedCountMiddleBandVariantsZeroKind(s.to_owned())
            }
            fn count_middle_band_variants(_items: &[Self]) -> usize {
                // Drift: return `0` regardless. Fires on the bimodal-
                // triple middle-band arm at `0 != 1` at cardinality
                // >= 3 — the SOLE canonical fixture witness the middle-
                // band cardinality corner has a strictly-positive arm.
                0
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedCountMiddleBandVariantsZeroKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedCountMiddleBandVariantsZeroKind whose count_middle_band_variants override folds onto `0` unconditionally — clause (146)'s bimodal-triple middle-band fixpoint arm MUST reject the drift (the SOLE canonical fixture witness the middle-band cardinality corner has a strictly-positive arm)",
        );
    }

