    #[test]
    fn has_middle_band_variant_agrees_with_de_morgan_complement_across_every_triple() {
        // DE MORGAN COMPLEMENT IDENTITY: for every slice `items`,
        // `T::has_middle_band_variant(items) == (!items.is_empty() && T::count_extremal_variants(items) < T::CARDINALITY)`
        // — the set-level bool predicate factors through the just-lifted
        // (set-level × usize × direction-composition × union)
        // T::count_extremal_variants aggregate via the De Morgan complement
        // of the (extreme / middle) partition on non-empty slices.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate = <StubKind as ClosedSet>::has_middle_band_variant(&triple);
                    let via_de_morgan = !triple.is_empty()
                        && <StubKind as ClosedSet>::count_extremal_variants(&triple)
                            < <StubKind as ClosedSet>::CARDINALITY;
                    assert_eq!(
                        via_predicate, via_de_morgan,
                        "T::has_middle_band_variant({triple:?}) diverged from (!items.is_empty() && T::count_extremal_variants({triple:?}) < T::CARDINALITY) — the De Morgan complement identity was violated",
                    );
                }
            }
        }
        let empty: &[StubKind] = &[];
        let via_predicate = <StubKind as ClosedSet>::has_middle_band_variant(empty);
        let via_de_morgan = !empty.is_empty()
            && <StubKind as ClosedSet>::count_extremal_variants(empty)
                < <StubKind as ClosedSet>::CARDINALITY;
        assert_eq!(via_predicate, via_de_morgan);
    }

