    fn has_bimodal_variant_returns_false_on_every_matching_singleton_at_cardinality_gte_two_across_every_variant(
    ) {
        // MATCHING-SINGLETON CONTRACT AT CARDINALITY `>= 2`: the sole
        // position hits `v` at count `1 == max` while every non-target
        // variant sits at count `0 == min`, the histogram is non-flat,
        // T::count_bimodal_variants reports `0`, and `0 < 1`. StubKind
        // has cardinality 3 so this arm fires. LOAD-BEARING `false`-arm
        // catch separating the intersection existence corner from the
        // (prospective) union existence corner `has_extremal_variant`
        // which reports `true` on the same fixture.
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert!(
                !<StubKind as ClosedSet>::has_bimodal_variant(&singleton),
                "T::has_bimodal_variant({singleton:?}) diverged from the matching-singleton fixpoint `false` at variant {v:?}",
            );
        }
    }

