    #[test]
    fn has_extremal_variant_equals_slice_non_emptiness_across_every_triple() {
        // NON-EMPTINESS COLLAPSE IDENTITY: for every slice `items`,
        // `T::has_extremal_variant(items) == !items.is_empty()` — the
        // canonical form the body uses. The union-arm existence bit
        // SHARPENS to the bare non-emptiness bit because every non-
        // empty slice carries an argmax target under
        // T::is_modal_variant_of. Sweeping every length-3 triple pins
        // the identity across the full 27-corner domain past the
        // empty-slice endpoint.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::has_extremal_variant(empty),
            !empty.is_empty(),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate = <StubKind as ClosedSet>::has_extremal_variant(&triple);
                    let via_non_emptiness = !triple.is_empty();
                    assert_eq!(
                        via_predicate, via_non_emptiness,
                        "T::has_extremal_variant({triple:?}) diverged from !items.is_empty() — the non-emptiness collapse identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn has_extremal_variant_equals_count_extremal_variants_ge_one_across_every_triple() {
        // COUNT-COMPOSITION IDENTITY: for every slice `items`,
        // `T::has_extremal_variant(items) == (T::count_extremal_variants(items) >= 1)`
        // — the equivalent-but-slower canonical form pre-SHARPENING.
        // Independent cross-check distinct from the non-emptiness
        // collapse arm on the compilation-shape (count-and-compare vs
        // slice-header-test) axis.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate = <StubKind as ClosedSet>::has_extremal_variant(&triple);
                    let via_count = <StubKind as ClosedSet>::count_extremal_variants(&triple) >= 1;
                    assert_eq!(
                        via_predicate, via_count,
                        "T::has_extremal_variant({triple:?}) diverged from (T::count_extremal_variants({triple:?}) >= 1) — the count-composition identity was violated",
                    );
                }
            }
        }
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::has_extremal_variant(empty),
            <StubKind as ClosedSet>::count_extremal_variants(empty) >= 1,
        );
    }

    #[test]
    fn has_extremal_variant_equals_existential_of_is_extremal_variant_of_across_every_triple() {
        // EXISTENTIAL-LIFT IDENTITY: for every slice `items`,
        // `T::has_extremal_variant(items) == T::ALL.iter().copied().any(|v| T::is_extremal_variant_of(v, items))`
        // — the set-level bool predicate is the EXACT existential
        // quantification over T::ALL of the per-target extremal
        // predicate.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_predicate = <StubKind as ClosedSet>::has_extremal_variant(&triple);
                    let via_any = <StubKind as ClosedSet>::ALL
                        .iter()
                        .copied()
                        .any(|v| <StubKind as ClosedSet>::is_extremal_variant_of(v, &triple));
                    assert_eq!(
                        via_predicate, via_any,
                        "T::has_extremal_variant({triple:?}) diverged from T::ALL.iter().copied().any(|v| T::is_extremal_variant_of(v, {triple:?})) — the existential-lift identity was violated",
                    );
                }
            }
        }
        let empty: &[StubKind] = &[];
        let via_predicate = <StubKind as ClosedSet>::has_extremal_variant(empty);
        let via_any = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .any(|v| <StubKind as ClosedSet>::is_extremal_variant_of(v, empty));
        assert_eq!(via_predicate, via_any);
    }

    #[test]
    fn has_extremal_variant_subsumes_has_bimodal_variant_or_has_middle_band_variant_on_non_empty_across_every_triple(
    ) {
        // TRICHOTOMY SUBSUMPTION IDENTITY: for every NON-EMPTY slice
        // `items`,
        // `T::has_extremal_variant(items) == (T::has_bimodal_variant(items) || T::has_middle_band_variant(items) || (!T::has_bimodal_variant(items) && !T::has_middle_band_variant(items)))`
        // — EQUIVALENTLY `T::has_extremal_variant(items) == true` on
        // every non-empty slice because the union-arm existence bit
        // SATURATES the non-empty domain. This binds the (set-level ×
        // bool × direction-composition × existential) trichotomy — the
        // union bit always fires on non-empty, subsuming BOTH the
        // intersection and complement bits which are mutually exclusive
        // via the (intersection / complement) De Morgan split.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let extremal = <StubKind as ClosedSet>::has_extremal_variant(&triple);
                    let bimodal = <StubKind as ClosedSet>::has_bimodal_variant(&triple);
                    let middle_band = <StubKind as ClosedSet>::has_middle_band_variant(&triple);
                    // Union-arm SATURATION on non-empty.
                    assert!(
                        extremal,
                        "T::has_extremal_variant({triple:?}) = false on a non-empty slice — the union-arm existence bit MUST SATURATE the non-empty domain",
                    );
                    // Trichotomy subsumption: extremal >= (bimodal || middle_band).
                    assert!(
                        extremal || !(bimodal || middle_band),
                        "T::has_extremal_variant({triple:?}) = {extremal} but bimodal = {bimodal} OR middle_band = {middle_band} fired — the union bit MUST subsume both partition arms",
                    );
                    // Bimodal-vs-middle-band De Morgan on non-empty.
                    assert!(
                        !(bimodal && middle_band),
                        "T::has_bimodal_variant({triple:?}) = {bimodal} AND T::has_middle_band_variant({triple:?}) = {middle_band} — the two bits MUST be mutually exclusive on non-empty",
                    );
                }
            }
        }
    }

    #[test]
    fn has_extremal_variant_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // the standard-library `<[Self]>::is_empty` slice-header bit
        // which is trivially reversal-invariant (reversing a slice
        // preserves its length).
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::has_extremal_variant(&triple);
                    let via_reversed = <StubKind as ClosedSet>::has_extremal_variant(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::has_extremal_variant({triple:?}) diverged from T::has_extremal_variant({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

