    #[test]
    fn sorted_middle_band_variants_agrees_with_lex_set_difference_of_sorted_variants_and_extremal_variants_across_every_triple(
    ) {
        // COMPLEMENT-COMPOSITION IDENTITY: for every NON-EMPTY slice
        // `items`, `T::sorted_middle_band_variants(items)` equals the
        // LEX-ORDER set-difference of T::sorted_variants() and
        // T::extremal_variants(items). On the empty slice the middle-
        // band projection collapses to Vec::new() via its non-emptiness
        // guard while the naive lex-set-difference walks
        // T::sorted_variants() and finds nothing in the empty
        // extremal_variants — the identity holds ONLY on non-empty
        // slices.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_middle_band =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    let via_diff: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
                        .into_iter()
                        .filter(|v| !extremal.contains(v))
                        .collect();
                    assert_eq!(
                        via_middle_band, via_diff,
                        "T::sorted_middle_band_variants({triple:?}) diverged from the lex-order set-difference of T::sorted_variants() and T::extremal_variants({triple:?}) — the complement-composition identity was violated on a non-empty slice",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_middle_band_variants_and_extremal_variants_are_disjoint_across_every_triple() {
        // DISJOINTNESS IDENTITY: for every slice `items`,
        // `T::sorted_middle_band_variants(items)` and
        // `T::extremal_variants(items)` share NO common variant — the
        // (extreme / middle) partition of the closed set on non-empty
        // slices is DISJOINT by construction (a variant's count either
        // sits at max/min or strictly between, never both). On the
        // empty slice both collapse to Vec::new() and disjointness
        // holds trivially.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let sorted_middle_band =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple);
                    let extremal = <StubKind as ClosedSet>::extremal_variants(&triple);
                    for v in sorted_middle_band.iter() {
                        assert!(
                            !extremal.contains(v),
                            "T::sorted_middle_band_variants({triple:?}) shares variant {v:?} with T::extremal_variants({triple:?}) — the (extreme / middle) partition disjointness identity was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn sorted_middle_band_variants_is_a_lex_permutation_of_middle_band_variants_across_every_triple(
    ) {
        // MULTISET-AGREEMENT IDENTITY: for every slice `items`,
        // `T::sorted_middle_band_variants(items)` is a LEX-ORDER
        // PERMUTATION of `T::middle_band_variants(items)` — both
        // projections filter under the same strict-interior conjunction
        // `c != max && c != min` and agree as multisets, differing
        // ONLY in walk order (declaration vs lex). Sweeping every
        // length-3 triple pins the multiset-equality identity by
        // asserting the sorted-index projections agree element-for-
        // element.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let mut decl_indices: Vec<usize> =
                        <StubKind as ClosedSet>::middle_band_variants(&triple)
                            .into_iter()
                            .map(<StubKind as ClosedSet>::index_of)
                            .collect();
                    let mut lex_indices: Vec<usize> =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple)
                            .into_iter()
                            .map(<StubKind as ClosedSet>::index_of)
                            .collect();
                    decl_indices.sort_unstable();
                    lex_indices.sort_unstable();
                    assert_eq!(
                        decl_indices, lex_indices,
                        "T::sorted_middle_band_variants({triple:?}) and T::middle_band_variants({triple:?}) diverged as multisets — both projections MUST filter under the same strict-interior predicate and thus agree as multisets, differing ONLY in walk order",
                    );
                }
            }
        }
    }

