    #[test]
    fn sorted_extremal_variants_returns_all_but_middle_band_on_the_bimodal_triple_at_cardinality_gte_three(
    ) {
        // BIMODAL-TRIPLE CONTRACT AT CARDINALITY `>= 3`: on
        // `[T::ALL[0], T::ALL[0], T::ALL[1]]` the histogram is
        // (T::ALL[0] -> 2 == max, T::ALL[1] -> 1 == MIDDLE, T::ALL[2]
        // -> 0 == min); T::ALL[1] is EXCLUDED from the union arm, and
        // T::ALL[0] + T::ALL[2] are INCLUDED via one of the two
        // extreme arms. LOAD-BEARING SOLE canonical fixture where this
        // projection populates a proper subset of T::sorted_variants
        // at cardinality `T::CARDINALITY - 1` (strictly between the
        // empty-vec and full-list fixpoints).
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        let bimodal_triple = [
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[1],
        ];
        let sorted_extremal = <StubKind as ClosedSet>::sorted_extremal_variants(&bimodal_triple);
        let expected: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
            .into_iter()
            .filter(|&v| {
                <StubKind as ClosedSet>::index_of(v)
                    != <StubKind as ClosedSet>::index_of(<StubKind as ClosedSet>::ALL[1])
            })
            .collect();
        assert_eq!(
            sorted_extremal.len(),
            <StubKind as ClosedSet>::CARDINALITY - 1,
            "T::sorted_extremal_variants(&bimodal_triple).len() diverged from T::CARDINALITY - 1 on the bimodal-triple fixpoint",
        );
        assert_eq!(
            sorted_extremal, expected,
            "T::sorted_extremal_variants({bimodal_triple:?}) diverged from T::sorted_variants() minus T::ALL[1] on the bimodal-triple fixpoint",
        );
    }

    #[test]
    fn sorted_extremal_variants_len_agrees_with_count_extremal_variants_across_every_triple() {
        // LENGTH-COMPOSITION IDENTITY: for every slice `items`,
        // `T::sorted_extremal_variants(items).len() == T::count_extremal_variants(items)`
        // — the plural's LEN equals the just-lifted cardinality-count
        // aggregate because both projections filter under the same
        // direction-composition predicate; ordering does NOT affect
        // cardinality.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_extremal_variants(empty).len(),
            <StubKind as ClosedSet>::count_extremal_variants(empty),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_plural =
                        <StubKind as ClosedSet>::sorted_extremal_variants(&triple).len();
                    let via_scalar = <StubKind as ClosedSet>::count_extremal_variants(&triple);
                    assert_eq!(
                        via_plural, via_scalar,
                        "T::sorted_extremal_variants({triple:?}).len() diverged from T::count_extremal_variants({triple:?}) — the length-composition identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_extremal_variants_agrees_with_filter_of_is_extremal_variant_of_across_every_triple() {
        // FILTER-COUNT IDENTITY: for every slice `items`,
        // `T::sorted_extremal_variants(items) == T::sorted_variants().into_iter().filter(|&v| T::is_extremal_variant_of(v, items)).collect()`
        // — the sharpened max/min-fold body agrees with the naive
        // per-target filter over T::sorted_variants on the
        // composition-shape axis.
        let empty: &[StubKind] = &[];
        let via_sharpened = <StubKind as ClosedSet>::sorted_extremal_variants(empty);
        let via_naive: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
            .into_iter()
            .filter(|&v| <StubKind as ClosedSet>::is_extremal_variant_of(v, empty))
            .collect();
        assert_eq!(via_sharpened, via_naive);
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_sharpened = <StubKind as ClosedSet>::sorted_extremal_variants(&triple);
                    let via_naive: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
                        .into_iter()
                        .filter(|&v| <StubKind as ClosedSet>::is_extremal_variant_of(v, &triple))
                        .collect();
                    assert_eq!(
                        via_sharpened, via_naive,
                        "T::sorted_extremal_variants({triple:?}) diverged from T::sorted_variants().into_iter().filter(|v| T::is_extremal_variant_of(v, {triple:?})).collect() — the filter-count identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_extremal_variants_agrees_with_lex_set_difference_of_sorted_variants_and_sorted_middle_band_variants_across_every_triple(
    ) {
        // COMPLEMENT-PARTITION IDENTITY: for every NON-EMPTY slice
        // `items`, `T::sorted_extremal_variants(items)` equals the
        // LEX-ORDER set-difference of T::sorted_variants() and
        // T::sorted_middle_band_variants(items). On the empty slice
        // both extremal and middle-band projections collapse to
        // Vec::new() via the shared non-emptiness guard while the naive
        // lex-set-difference `T::sorted_variants().into_iter()
        // .filter(|v| !T::sorted_middle_band_variants(&[]).contains(v))
        // .collect()` returns T::sorted_variants() intact — the
        // identity holds ONLY on non-empty slices.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_extremal = <StubKind as ClosedSet>::sorted_extremal_variants(&triple);
                    let middle_band = <StubKind as ClosedSet>::sorted_middle_band_variants(&triple);
                    let via_diff: Vec<StubKind> = <StubKind as ClosedSet>::sorted_variants()
                        .into_iter()
                        .filter(|v| !middle_band.contains(v))
                        .collect();
                    assert_eq!(
                        via_extremal, via_diff,
                        "T::sorted_extremal_variants({triple:?}) diverged from the lex-order set-difference of T::sorted_variants() and T::sorted_middle_band_variants({triple:?}) — the complement-partition identity was violated on a non-empty slice",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_extremal_variants_and_sorted_middle_band_variants_are_disjoint_across_every_triple() {
        // DISJOINTNESS IDENTITY: for every slice `items`,
        // `T::sorted_extremal_variants(items)` and
        // `T::sorted_middle_band_variants(items)` share NO common
        // variant — the (extreme / middle) partition of the closed set
        // on non-empty slices is DISJOINT by construction (a variant's
        // count either sits at max/min or strictly between, never
        // both). On the empty slice both collapse to Vec::new() and
        // disjointness holds trivially.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let sorted_extremal =
                        <StubKind as ClosedSet>::sorted_extremal_variants(&triple);
                    let sorted_middle_band =
                        <StubKind as ClosedSet>::sorted_middle_band_variants(&triple);
                    for v in sorted_extremal.iter() {
                        assert!(
                            !sorted_middle_band.contains(v),
                            "T::sorted_extremal_variants({triple:?}) shares variant {v:?} with T::sorted_middle_band_variants({triple:?}) — the (extreme / middle) partition disjointness identity was violated",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn sorted_extremal_variants_is_a_lex_permutation_of_extremal_variants_across_every_triple() {
        // MULTISET-AGREEMENT IDENTITY: for every slice `items`,
        // `T::sorted_extremal_variants(items)` is a LEX-ORDER
        // PERMUTATION of `T::extremal_variants(items)` — both
        // projections filter under the same union disjunction
        // `c == max || c == min` and agree as multisets, differing
        // ONLY in walk order (declaration vs lex). Sweeping every
        // length-3 triple pins the multiset-equality identity by
        // asserting the sorted-index projections agree element-for-
        // element.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let mut decl_indices: Vec<usize> =
                        <StubKind as ClosedSet>::extremal_variants(&triple)
                            .into_iter()
                            .map(<StubKind as ClosedSet>::index_of)
                            .collect();
                    let mut lex_indices: Vec<usize> =
                        <StubKind as ClosedSet>::sorted_extremal_variants(&triple)
                            .into_iter()
                            .map(<StubKind as ClosedSet>::index_of)
                            .collect();
                    decl_indices.sort_unstable();
                    lex_indices.sort_unstable();
                    assert_eq!(
                        decl_indices, lex_indices,
                        "T::sorted_extremal_variants({triple:?}) and T::extremal_variants({triple:?}) diverged as multisets — both projections MUST filter under the same union disjunction and thus agree as multisets, differing ONLY in walk order",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_extremal_variants_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // the ordering-agnostic max/min-fold pair + a walk over
        // T::sorted_variants (which does NOT depend on `items`
        // ordering); reversing `items` preserves its variant multiset,
        // so the projection is a function of that multiset alone.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::sorted_extremal_variants(&triple);
                    let via_reversed = <StubKind as ClosedSet>::sorted_extremal_variants(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::sorted_extremal_variants({triple:?}) diverged from T::sorted_extremal_variants({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

