    #[test]
    fn sorted_extremal_variant_is_some_iff_extremal_variant_is_some_across_every_triple() {
        // SIBLING-COMPOSITION IDENTITY (LEX ↔ DECL is-some alignment):
        // for every slice `items`,
        // `T::sorted_extremal_variant(items).is_some() ==
        // T::extremal_variant(items).is_some()` — the (Some, None)
        // partition of the LEX-order first-witness AGREES with the
        // (Some, None) partition of the DECLARATION-order first-
        // witness on every slice. The two projections may disagree on
        // the VALUE they report inside the Some arm on any slice whose
        // union band spans a (T::first() != T::sorted_first())-divergent
        // split, but they AGREE on WHEN the Some arm fires. This
        // catches an override whose empty-slice guard drifts on ONE
        // ordering arm but not the other.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_extremal_variant(empty).is_some(),
            <StubKind as ClosedSet>::extremal_variant(empty).is_some(),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_lex =
                        <StubKind as ClosedSet>::sorted_extremal_variant(&triple).is_some();
                    let via_decl = <StubKind as ClosedSet>::extremal_variant(&triple).is_some();
                    assert_eq!(
                        via_lex, via_decl,
                        "T::sorted_extremal_variant({triple:?}).is_some() diverged from T::extremal_variant({triple:?}).is_some() — the LEX ↔ DECL is-some alignment was violated",
                    );
                }
            }
        }
    }

