    #[test]
    fn sorted_extremal_variant_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // the ordering-agnostic max/min-fold pair + a walk over
        // T::sorted_variants() in LEX order — the (declaration, lex)
        // axis on the SLICE side collapses on element equality because
        // max/min are functions of the multiset alone. Sibling posture
        // to
        // `extremal_variant_is_invariant_under_slice_reversal_across_every_triple`
        // one ORDERING axis over.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::sorted_extremal_variant(&triple);
                    let via_reversed = <StubKind as ClosedSet>::sorted_extremal_variant(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::sorted_extremal_variant({triple:?}) diverged from T::sorted_extremal_variant({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_extremal_variant_agrees_with_lex_order_find_across_every_triple() {
        // NAIVE-FIND IDENTITY: for every slice `items`,
        // `T::sorted_extremal_variant(items)` agrees with the naive
        // LEX-order `find` sweep binding the union predicate `c == max
        // || c == min` composed against T::sorted_variants(). Catches
        // an override that accidentally walks T::ALL (the declaration-
        // order sibling's walk surface) instead of T::sorted_variants
        // on any implementor whose declaration order diverges from lex
        // order.
        let empty: &[StubKind] = &[];
        let via_sharpened = <StubKind as ClosedSet>::sorted_extremal_variant(empty);
        let via_naive: Option<StubKind> = if empty.is_empty() {
            None
        } else {
            let max = <StubKind as ClosedSet>::max_variant_count(empty);
            let min = <StubKind as ClosedSet>::min_variant_count(empty);
            <StubKind as ClosedSet>::sorted_variants()
                .into_iter()
                .find(|&v| {
                    let cnt = <StubKind as ClosedSet>::count_occurrences_of(v, empty);
                    cnt == max || cnt == min
                })
        };
        assert_eq!(via_sharpened, via_naive);
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_sharpened = <StubKind as ClosedSet>::sorted_extremal_variant(&triple);
                    let via_naive: Option<StubKind> = if triple.is_empty() {
                        None
                    } else {
                        let max = <StubKind as ClosedSet>::max_variant_count(&triple);
                        let min = <StubKind as ClosedSet>::min_variant_count(&triple);
                        <StubKind as ClosedSet>::sorted_variants()
                            .into_iter()
                            .find(|&v| {
                                let cnt = <StubKind as ClosedSet>::count_occurrences_of(v, &triple);
                                cnt == max || cnt == min
                            })
                    };
                    assert_eq!(
                        via_sharpened, via_naive,
                        "T::sorted_extremal_variant({triple:?}) diverged from the naive LEX-order find sweep — the naive-find identity was violated",
                    );
                }
            }
        }
    }

