    #[test]
    fn middle_band_variant_equals_first_of_middle_band_variants_across_every_triple() {
        // FIRST-WITNESS-OF-PLURAL IDENTITY: for every slice `items`,
        // `T::middle_band_variant(items) ==
        // T::middle_band_variants(items).first().copied()` — the
        // singular OPTION-return direction-composition complement
        // first-witness AGREES with the FIRST element of the plural
        // VEC-return direction-composition complement witness-
        // collection walked in the same declaration-order canonical
        // order.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::middle_band_variant(empty),
            <StubKind as ClosedSet>::middle_band_variants(empty)
                .first()
                .copied(),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_singular = <StubKind as ClosedSet>::middle_band_variant(&triple);
                    let via_plural = <StubKind as ClosedSet>::middle_band_variants(&triple)
                        .first()
                        .copied();
                    assert_eq!(
                        via_singular, via_plural,
                        "T::middle_band_variant({triple:?}) diverged from T::middle_band_variants({triple:?}).first().copied() — the first-witness-of-plural identity was violated",
                    );
                }
            }
        }
    }

