    #[test]
    fn middle_band_variant_agrees_with_declaration_order_find_across_every_triple() {
        // NAIVE-FIND IDENTITY: for every slice `items`,
        // `T::middle_band_variant(items)` agrees with the naive
        // declaration-order `find` sweep binding the complement
        // predicate `c != max && c != min`.
        let empty: &[StubKind] = &[];
        let via_sharpened = <StubKind as ClosedSet>::middle_band_variant(empty);
        let via_naive: Option<StubKind> = if empty.is_empty() {
            None
        } else {
            let max = <StubKind as ClosedSet>::max_variant_count(empty);
            let min = <StubKind as ClosedSet>::min_variant_count(empty);
            <StubKind as ClosedSet>::ALL.iter().copied().find(|&v| {
                let cnt = <StubKind as ClosedSet>::count_occurrences_of(v, empty);
                cnt != max && cnt != min
            })
        };
        assert_eq!(via_sharpened, via_naive);
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_sharpened = <StubKind as ClosedSet>::middle_band_variant(&triple);
                    let via_naive: Option<StubKind> = if triple.is_empty() {
                        None
                    } else {
                        let max = <StubKind as ClosedSet>::max_variant_count(&triple);
                        let min = <StubKind as ClosedSet>::min_variant_count(&triple);
                        <StubKind as ClosedSet>::ALL.iter().copied().find(|&v| {
                            let cnt = <StubKind as ClosedSet>::count_occurrences_of(v, &triple);
                            cnt != max && cnt != min
                        })
                    };
                    assert_eq!(
                        via_sharpened, via_naive,
                        "T::middle_band_variant({triple:?}) diverged from the naive declaration-order find sweep — the naive-find identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_none_drift_in_middle_band_variant() {
        // Drift catch — clause (158)'s bimodal-triple fixpoint arm
        // fires when an override folds the set-level direction-
        // composition complement first-witness onto None
        // unconditionally.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedMiddleBandVariantNoneKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedMiddleBandVariantNoneKind(pub String);

        impl core::fmt::Display for UnknownDriftedMiddleBandVariantNoneKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted middle band variant none kind: {}",
                    self.0
                )
            }
        }

        impl DriftedMiddleBandVariantNoneKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedMiddleBandVariantNoneKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted middle band variant none kind";
            type Unknown = UnknownDriftedMiddleBandVariantNoneKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedMiddleBandVariantNoneKind(s.to_owned())
            }
            fn middle_band_variant(_items: &[Self]) -> Option<Self> {
                // Drift: return None regardless. Fires on the bimodal-
                // triple arm at `None != Some(T::ALL[1])`.
                None
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedMiddleBandVariantNoneKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedMiddleBandVariantNoneKind whose middle_band_variant override folds onto None unconditionally — clause (158)'s bimodal-triple fixpoint arm MUST reject the drift (the SOLE Some-arm on the canonical fixture window)",
        );
    }

