    #[test]
    fn sorted_bimodal_variant_returns_none_on_the_empty_slice_across_every_kind() {
        // EMPTY-SLICE CONTRACT (set-level × Option<Self> × statistical-
        // aggregate × direction-composition × intersection × lex-order):
        // the empty slice hits zero positions, T::max_variant_count and
        // T::min_variant_count both collapse to 0, T::is_uniform reports
        // `true` vacuously (max == min == 0), but the empty guard
        // SHORT-CIRCUITS past the vacuous flat-histogram collapse and
        // lands on None. LOAD-BEARING None-arm past an unguarded branch
        // that would silently return Some(T::sorted_first()) — the
        // WRONG structural answer. Sibling posture to
        // `bimodal_variant_returns_none_on_the_empty_slice_across_every_kind`
        // one ORDERING axis over: BOTH the declaration-order and
        // lex-order intersection projections carry the SAME empty-slice
        // guard because the (max == min == 0) degenerate arm applies
        // identically under either walk surface.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_bimodal_variant(empty),
            None,
            "T::sorted_bimodal_variant(&[]) diverged from the empty-slice fixpoint None",
        );
    }

    #[test]
    fn sorted_bimodal_variant_returns_none_on_every_matching_singleton_across_every_variant() {
        // MATCHING-SINGLETON CONTRACT AT CARDINALITY `>= 2`: the sole
        // position hits `v` at count `1 == max`, every non-target
        // variant sits at count `0 == min`, so the histogram is
        // non-flat (max `1` != min `0`), T::is_uniform reports `false`,
        // and the dichotomy lands on None. LOAD-BEARING None-arm
        // DISCRIMINATING this LEX-order INTERSECTION projection from
        // the LEX-order UNION sibling `sorted_extremal_variant` (which
        // reports Some(T::sorted_first()) on the same fixture via the
        // (max ∨ min) union covering every variant through one of the
        // two arms). Sibling posture to
        // `bimodal_variant_returns_none_on_every_matching_singleton_across_every_variant`
        // one ORDERING axis over: BOTH the declaration-order and
        // lex-order intersection projections pin the matching-singleton
        // arm to `None` independently of walk order because the
        // uniformity dichotomy is ORDERING-agnostic.
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            let singleton = [v];
            assert_eq!(
                <StubKind as ClosedSet>::sorted_bimodal_variant(&singleton),
                None,
                "T::sorted_bimodal_variant({singleton:?}) diverged from None at the matching-singleton fixpoint at variant {v:?}",
            );
        }
    }

    #[test]
    fn sorted_bimodal_variant_returns_some_sorted_first_on_the_full_set_across_every_kind() {
        // FULL-SET CONTRACT: pairwise-distinctness pins every variant
        // at exactly one position, T::max_variant_count ==
        // T::min_variant_count == 1 on the flat-histogram fixpoint,
        // every variant sits at BOTH extremes via the (max == min ==
        // 1) collapse, T::is_uniform reports `true`, and the lex-order
        // first-witness lands on T::sorted_first() immediately. The
        // LOAD-BEARING flat-histogram Some-arm DISCRIMINATING this
        // LEX-order INTERSECTION projection from the LEX-order
        // COMPLEMENT sibling `sorted_middle_band_variant` (which
        // reports None on the same fixture — the flat-histogram
        // collapse pins the middle band as empty while pinning the
        // intersection band as full).
        assert_eq!(
            <StubKind as ClosedSet>::sorted_bimodal_variant(
                <StubKind as ClosedSet>::ALL,
            ),
            Some(<StubKind as ClosedSet>::sorted_first()),
            "T::sorted_bimodal_variant(T::ALL) diverged from Some(T::sorted_first()) at the flat-histogram fixpoint",
        );
    }

    #[test]
    fn sorted_bimodal_variant_returns_some_sorted_first_on_the_doubled_full_set_across_every_kind()
    {
        // DOUBLED-FULL-SET CONTRACT: max == min == 2, every variant
        // sits at BOTH extremes via the second flat-histogram
        // fixpoint, T::is_uniform reports `true`, and the lex-order
        // first-witness lands on T::sorted_first() immediately.
        let doubled: Vec<StubKind> = <StubKind as ClosedSet>::ALL
            .iter()
            .copied()
            .chain(<StubKind as ClosedSet>::ALL.iter().copied())
            .collect();
        assert_eq!(
            <StubKind as ClosedSet>::sorted_bimodal_variant(&doubled),
            Some(<StubKind as ClosedSet>::sorted_first()),
            "T::sorted_bimodal_variant(ALL++ALL) diverged from Some(T::sorted_first()) at the doubled-full-set fixpoint",
        );
    }

    #[test]
    fn sorted_bimodal_variant_returns_none_on_the_bimodal_triple_at_cardinality_gte_three() {
        // BIMODAL-TRIPLE CONTRACT AT CARDINALITY `>= 3`: on
        // `[T::ALL[0], T::ALL[0], T::ALL[1]]` the histogram is
        // (T::ALL[0] -> 2 == max, T::ALL[1] -> 1 == MIDDLE, T::ALL[2]
        // -> 0 == min); the histogram is non-flat (max `2` != min
        // `0`), T::is_uniform reports `false`, and the dichotomy lands
        // on None. The LOAD-BEARING None-arm on the SAME canonical
        // fixture where sorted_middle_band_variant reports
        // Some(T::sorted_variants()[1]) and sorted_extremal_variant
        // reports Some(T::sorted_first()) — the three lex-order
        // projections split the modal-aggregation matrix into its
        // three direction-composition arms on the ONE canonical
        // non-flat triple.
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        let bimodal_triple = [
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[1],
        ];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_bimodal_variant(&bimodal_triple),
            None,
            "T::sorted_bimodal_variant({bimodal_triple:?}) diverged from None at the bimodal-triple fixpoint",
        );
    }

    #[test]
    fn sorted_bimodal_variant_returns_some_sorted_first_iff_slice_is_non_empty_and_uniform_across_every_triple(
    ) {
        // UNIFORMITY-COLLAPSE DICHOTOMY: for every slice `items`,
        // `T::sorted_bimodal_variant(items) == Some(T::sorted_first())`
        // iff `items` is NON-EMPTY AND T::is_uniform holds, else None.
        // The independent cross-check on the composition-shape
        // (uniformity-collapse vs per-variant flat-diagonal filter)
        // axis binds every enumerated triple against the sharpened
        // dichotomy.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_sharpened = <StubKind as ClosedSet>::sorted_bimodal_variant(&triple);
                    let expected: Option<StubKind> =
                        if triple.is_empty() || !<StubKind as ClosedSet>::is_uniform(&triple) {
                            None
                        } else {
                            <StubKind as ClosedSet>::sorted_variants().first().copied()
                        };
                    assert_eq!(
                        via_sharpened, expected,
                        "T::sorted_bimodal_variant({triple:?}) diverged from the uniformity-collapse dichotomy — the sharpened body was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_bimodal_variant_equals_first_of_sorted_bimodal_variants_across_every_triple() {
        // FIRST-WITNESS-OF-PLURAL IDENTITY: for every slice `items`,
        // `T::sorted_bimodal_variant(items) ==
        // T::sorted_bimodal_variants(items).first().copied()` — the
        // singular OPTION-return LEX-order direction-composition
        // intersection first-witness AGREES with the FIRST element of
        // the plural VEC-return LEX-order direction-composition
        // intersection witness-collection walked in the same lex-order
        // canonical order. Sibling posture to
        // `bimodal_variant_equals_first_of_bimodal_variants_across_every_triple`
        // one ORDERING axis over.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_bimodal_variant(empty),
            <StubKind as ClosedSet>::sorted_bimodal_variants(empty)
                .first()
                .copied(),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_singular = <StubKind as ClosedSet>::sorted_bimodal_variant(&triple);
                    let via_plural = <StubKind as ClosedSet>::sorted_bimodal_variants(&triple)
                        .first()
                        .copied();
                    assert_eq!(
                        via_singular, via_plural,
                        "T::sorted_bimodal_variant({triple:?}) diverged from T::sorted_bimodal_variants({triple:?}).first().copied() — the first-witness-of-plural identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_bimodal_variant_is_some_iff_has_bimodal_variant_across_every_triple() {
        // IS-SOME-COMPOSITION IDENTITY: for every slice `items`,
        // `T::sorted_bimodal_variant(items).is_some() ==
        // T::has_bimodal_variant(items)` — the OPTION-return LEX-order
        // intersection first-witness is Some iff the BOOL-return
        // existential predicate (which is ordering-agnostic) holds.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_bimodal_variant(empty).is_some(),
            <StubKind as ClosedSet>::has_bimodal_variant(empty),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_option =
                        <StubKind as ClosedSet>::sorted_bimodal_variant(&triple).is_some();
                    let via_bool = <StubKind as ClosedSet>::has_bimodal_variant(&triple);
                    assert_eq!(
                        via_option, via_bool,
                        "T::sorted_bimodal_variant({triple:?}).is_some() diverged from T::has_bimodal_variant({triple:?}) — the is-some-composition identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn sorted_bimodal_variant_is_some_iff_bimodal_variant_is_some_across_every_triple() {
        // SIBLING-COMPOSITION IDENTITY: for every slice `items`,
        // `T::sorted_bimodal_variant(items).is_some() ==
        // T::bimodal_variant(items).is_some()` — the (Some, None)
        // partition of the LEX-order intersection first-witness AGREES
        // with the (Some, None) partition of the declaration-order
        // intersection first-witness on every slice. Both projections
        // gate through the SAME uniformity dichotomy via
        // T::is_uniform, so their Some-vs-None fires coincide even on
        // implementors whose lex order diverges from declaration order.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::sorted_bimodal_variant(empty).is_some(),
            <StubKind as ClosedSet>::bimodal_variant(empty).is_some(),
        );
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_sorted =
                        <StubKind as ClosedSet>::sorted_bimodal_variant(&triple).is_some();
                    let via_decl = <StubKind as ClosedSet>::bimodal_variant(&triple).is_some();
                    assert_eq!(
                        via_sorted, via_decl,
                        "T::sorted_bimodal_variant({triple:?}).is_some() diverged from T::bimodal_variant({triple:?}).is_some() — the sibling-composition identity was violated",
                    );
                }
            }
        }
    }

