    #[test]
    fn has_unique_middle_band_variant_implies_has_middle_band_variant_across_every_triple() {
        // EXISTENCE-IMPLICATION IDENTITY: for every slice `items`,
        // `T::has_unique_middle_band_variant(items) ==>
        // T::has_middle_band_variant(items)` — a UNIQUE middle-band
        // witness trivially entails the EXISTENCE of a middle-band
        // witness (count == 1 implies count >= 1). Sweeping every
        // length-3 triple pins the implication across the full 27-
        // corner domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let uniqueness =
                        <StubKind as ClosedSet>::has_unique_middle_band_variant(&triple);
                    let existence = <StubKind as ClosedSet>::has_middle_band_variant(&triple);
                    assert!(
                        !uniqueness || existence,
                        "T::has_unique_middle_band_variant({triple:?}) drifted from the existence-implication contract — uniqueness `true` MUST imply existence `true`",
                    );
                }
            }
        }
    }

