    #[test]
    fn assert_closed_set_well_formed_catches_always_some_first_drift_in_unique_extremal_variant() {
        // Drift catch — clause (165)'s empty-slice + flat-histogram +
        // matching-singleton + bimodal-triple fixpoint arms fire when
        // an override folds the set-level unique-extremal-variant
        // witness onto `Some(T::first())` unconditionally. On the empty
        // slice T::unique_extremal_variant MUST return None
        // (has_unique_extremal_variant is false); on every non-empty
        // fixpoint at cardinality >= 2 the same None-arm holds. An
        // always-Some(first) override bifurcates every arm at
        // `Some(_) != None`.
        //
        // Note: no `always-None` drift-catch peer is possible on a
        // cardinality-3 stub — at T::CARDINALITY >= 2 the correct
        // unique-extremal-witness answer is `None` on EVERY canonical
        // fixture, so an always-None override matches truth structurally
        // (the degenerate-opener property clause (165) documents). The
        // structural catch for `None`-drifting overrides sits at
        // T::CARDINALITY == 1 in clause (165)'s guarded-lift arm on the
        // full-set fixpoint, out of reach of a multi-variant stub.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedUniqueExtremalVariantSomeFirstKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedUniqueExtremalVariantSomeFirstKind(pub String);

        impl core::fmt::Display for UnknownDriftedUniqueExtremalVariantSomeFirstKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted unique_extremal_variant some-first kind: {}",
                    self.0
                )
            }
        }

        impl DriftedUniqueExtremalVariantSomeFirstKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedUniqueExtremalVariantSomeFirstKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted unique_extremal_variant some-first kind";
            type Unknown = UnknownDriftedUniqueExtremalVariantSomeFirstKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedUniqueExtremalVariantSomeFirstKind(s.to_owned())
            }
            fn unique_extremal_variant(_items: &[Self]) -> Option<Self> {
                // Drift: always return Some(first). Fires clause (165)'s
                // empty-slice arm (Some(_) != None) AND every non-empty
                // fixpoint arm at cardinality >= 2 (Some(_) != None).
                Some(Self::Alpha)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedUniqueExtremalVariantSomeFirstKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedUniqueExtremalVariantSomeFirstKind whose unique_extremal_variant override folds onto Some(first) unconditionally — clause (165)'s empty-slice + flat-histogram + matching-singleton + bimodal-triple fixpoint arms MUST reject the drift",
        );
    }

