    #[test]
    fn assert_closed_set_well_formed_catches_always_some_first_drift_in_unique_middle_band_variant()
    {
        // Drift catch — clause (166)'s empty-slice + flat-histogram +
        // matching-singleton fixpoint arms fire when an override folds
        // the set-level unique-middle-band-variant witness onto
        // `Some(T::first())` unconditionally. On the empty slice
        // T::unique_middle_band_variant MUST return None
        // (has_unique_middle_band_variant is false); on every non-bimodal
        // fixpoint at cardinality >= 2 the same None-arm holds. An
        // always-Some(first) override bifurcates every None arm at
        // `Some(_) != None`.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedUniqueMiddleBandVariantSomeFirstKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedUniqueMiddleBandVariantSomeFirstKind(pub String);

        impl core::fmt::Display for UnknownDriftedUniqueMiddleBandVariantSomeFirstKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted unique_middle_band_variant some-first kind: {}",
                    self.0
                )
            }
        }

        impl DriftedUniqueMiddleBandVariantSomeFirstKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedUniqueMiddleBandVariantSomeFirstKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted unique_middle_band_variant some-first kind";
            type Unknown = UnknownDriftedUniqueMiddleBandVariantSomeFirstKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedUniqueMiddleBandVariantSomeFirstKind(s.to_owned())
            }
            fn unique_middle_band_variant(_items: &[Self]) -> Option<Self> {
                // Drift: always return Some(first). Fires clause (166)'s
                // empty-slice arm (Some(_) != None) AND every non-bimodal
                // fixpoint arm at cardinality >= 2 (Some(_) != None).
                Some(Self::Alpha)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedUniqueMiddleBandVariantSomeFirstKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedUniqueMiddleBandVariantSomeFirstKind whose unique_middle_band_variant override folds onto Some(first) unconditionally — clause (166)'s empty-slice + flat-histogram + matching-singleton fixpoint arms MUST reject the drift",
        );
    }

