    #[test]
    fn assert_closed_set_well_formed_catches_always_some_first_drift_in_unique_bimodal_variant() {
        // Drift catch — clause (167)'s empty-slice + full-set +
        // doubled-full-set + matching-singleton + bimodal-triple fixpoint
        // arms fire when an override folds the set-level
        // unique-bimodal-variant witness onto `Some(T::first())`
        // unconditionally. At CARDINALITY >= 2 the correct answer is
        // None on EVERY canonical fixture (count_bimodal_variants folds
        // through the two-value dichotomy {0, T::CARDINALITY}, neither
        // equal to 1), so an always-Some(first) override bifurcates every
        // None arm at `Some(_) != None`.
        //
        // Note: no `always-None` drift-catch peer is possible on a
        // cardinality-3 stub — at T::CARDINALITY >= 2 the correct
        // unique-bimodal answer is None on EVERY canonical fixture, so an
        // always-None override matches truth structurally (the
        // degenerate-opener property clause (167) documents, mirroring
        // clauses (164) + (165) one RETURN-SHAPE axis over). The
        // structural catch for `None`-drifting overrides sits at
        // T::CARDINALITY == 1 in clause (167)'s guarded-lift arm on the
        // full-set fixpoint, out of reach of a multi-variant stub.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedUniqueBimodalVariantSomeFirstKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedUniqueBimodalVariantSomeFirstKind(pub String);

        impl core::fmt::Display for UnknownDriftedUniqueBimodalVariantSomeFirstKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted unique_bimodal_variant some-first kind: {}",
                    self.0
                )
            }
        }

        impl DriftedUniqueBimodalVariantSomeFirstKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedUniqueBimodalVariantSomeFirstKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted unique_bimodal_variant some-first kind";
            type Unknown = UnknownDriftedUniqueBimodalVariantSomeFirstKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedUniqueBimodalVariantSomeFirstKind(s.to_owned())
            }
            fn unique_bimodal_variant(_items: &[Self]) -> Option<Self> {
                // Drift: always return Some(first). Fires clause (167)'s
                // empty-slice arm (Some(_) != None) AND every non-empty
                // fixpoint arm at cardinality >= 2 (Some(_) != None).
                Some(Self::Alpha)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedUniqueBimodalVariantSomeFirstKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedUniqueBimodalVariantSomeFirstKind whose unique_bimodal_variant override folds onto Some(first) unconditionally — clause (167)'s empty-slice + full-set + doubled-full-set + matching-singleton + bimodal-triple fixpoint arms MUST reject the drift",
        );
    }

