    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_is_unique_extremal_variant_of() {
        // Drift catch — clause (168)'s empty-slice + matching-singleton +
        // non-matching-singleton + flat-histogram + bimodal-triple fixpoint
        // arms fire when an override folds the per-target unique-extremum
        // predicate onto `true` unconditionally. Every canonical fixpoint
        // pins the projection at `false` at cardinality >= 2, so an
        // always-true override bifurcates every arm at `true != false`.
        //
        // Note: no `always-false` drift-catch peer is possible on a
        // cardinality-3 stub — at T::CARDINALITY >= 2 the correct
        // unique-extremum answer is `false` on EVERY canonical fixture
        // (mirroring the degenerate-opener property clauses (163) + (165)
        // document one ARITY axis over). The structural catch for
        // `false`-drifting overrides sits at T::CARDINALITY == 1, out of
        // reach of a multi-variant stub.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedIsUniqueExtremalVariantOfTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedIsUniqueExtremalVariantOfTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedIsUniqueExtremalVariantOfTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted is_unique_extremal_variant_of true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedIsUniqueExtremalVariantOfTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedIsUniqueExtremalVariantOfTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted is_unique_extremal_variant_of true kind";
            type Unknown = UnknownDriftedIsUniqueExtremalVariantOfTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedIsUniqueExtremalVariantOfTrueKind(s.to_owned())
            }
            fn is_unique_extremal_variant_of(_target: Self, _items: &[Self]) -> bool {
                // Drift: return `true` regardless. Fires clause (168)'s
                // empty-slice + matching-singleton + non-matching-
                // singleton + full-set + doubled-full-set + bimodal-triple
                // fixpoint arms all at `true != false`.
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedIsUniqueExtremalVariantOfTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedIsUniqueExtremalVariantOfTrueKind whose is_unique_extremal_variant_of override folds onto `true` unconditionally — clause (168)'s empty-slice + matching-singleton + non-matching-singleton + flat-histogram + bimodal-triple fixpoint arms MUST reject the drift",
        );
    }

