    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_is_unique_middle_band_variant_of()
    {
        // Drift catch — clause (169)'s empty-slice + matching-
        // singleton + non-matching-singleton + flat-histogram +
        // bimodal-triple fixpoint arms fire when an override folds
        // the per-target unique-strict-interior predicate onto `true`
        // regardless of target.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedIsUniqueMiddleBandVariantOfTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedIsUniqueMiddleBandVariantOfTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedIsUniqueMiddleBandVariantOfTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted is_unique_middle_band_variant_of true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedIsUniqueMiddleBandVariantOfTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedIsUniqueMiddleBandVariantOfTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted is_unique_middle_band_variant_of true kind";
            type Unknown = UnknownDriftedIsUniqueMiddleBandVariantOfTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedIsUniqueMiddleBandVariantOfTrueKind(s.to_owned())
            }
            fn is_unique_middle_band_variant_of(_target: Self, _items: &[Self]) -> bool {
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedIsUniqueMiddleBandVariantOfTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedIsUniqueMiddleBandVariantOfTrueKind whose is_unique_middle_band_variant_of override folds onto `true` unconditionally — clause (169)'s empty-slice + matching-singleton + flat-histogram fixpoint arms MUST reject the drift",
        );
    }

