    #[test]
    fn assert_closed_set_well_formed_catches_always_true_drift_in_is_unique_bimodal_variant_of() {
        // Drift catch — clause (170)'s empty-slice + matching-
        // singleton + non-matching-singleton + full-set +
        // doubled-full-set + bimodal-triple fixpoint arms fire when
        // an override folds the per-target unique-flat-diagonal
        // predicate onto `true` unconditionally. Every canonical
        // fixpoint pins the projection at `false` at cardinality >= 2,
        // so an always-true override bifurcates every arm at
        // `true != false`.
        //
        // Note: no `always-false` drift-catch peer is possible on a
        // cardinality-3 stub — at T::CARDINALITY >= 2 the correct
        // unique-flat-diagonal answer is `false` on EVERY canonical
        // fixture (mirroring the DOUBLY-DEGENERATE property clause
        // (170) documents: non-flat multi-variant collapses via the
        // membership arm, flat-histogram multi-variant collapses via
        // the uniqueness arm). The structural catch for `false`-
        // drifting overrides sits at T::CARDINALITY == 1, out of
        // reach of a multi-variant stub.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedIsUniqueBimodalVariantOfTrueKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedIsUniqueBimodalVariantOfTrueKind(pub String);

        impl core::fmt::Display for UnknownDriftedIsUniqueBimodalVariantOfTrueKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted is_unique_bimodal_variant_of true kind: {}",
                    self.0
                )
            }
        }

        impl DriftedIsUniqueBimodalVariantOfTrueKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedIsUniqueBimodalVariantOfTrueKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted is_unique_bimodal_variant_of true kind";
            type Unknown = UnknownDriftedIsUniqueBimodalVariantOfTrueKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedIsUniqueBimodalVariantOfTrueKind(s.to_owned())
            }
            fn is_unique_bimodal_variant_of(_target: Self, _items: &[Self]) -> bool {
                // Drift: return `true` regardless. Fires clause (170)'s
                // empty-slice + matching-singleton + non-matching-
                // singleton + full-set + doubled-full-set + bimodal-
                // triple fixpoint arms all at `true != false`.
                true
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedIsUniqueBimodalVariantOfTrueKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedIsUniqueBimodalVariantOfTrueKind whose is_unique_bimodal_variant_of override folds onto `true` unconditionally — clause (170)'s empty-slice + matching-singleton + non-matching-singleton + flat-histogram + bimodal-triple fixpoint arms MUST reject the drift",
        );
    }

