    #[test]
    fn unique_repeating_variant_equals_has_unique_repeating_variant_gated_find_across_every_triple()
    {
        // GUARDED-FIRST-WITNESS IDENTITY: for every slice `items`,
        // `T::unique_repeating_variant(items) == if
        // T::has_unique_repeating_variant(items) {
        // T::ALL.iter().copied().find(|&v| T::is_repeated_occurrence_of(
        // v, items)) } else { None }` — the canonical form the body
        // uses. Sweeping every length-3 triple pins the identity across
        // the full 27-corner domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_projection = <StubKind as ClosedSet>::unique_repeating_variant(&triple);
                    let via_guarded_find =
                        if <StubKind as ClosedSet>::has_unique_repeating_variant(&triple) {
                            <StubKind as ClosedSet>::ALL.iter().copied().find(|&v| {
                                <StubKind as ClosedSet>::is_repeated_occurrence_of(v, &triple)
                            })
                        } else {
                            None
                        };
                    assert_eq!(
                        via_projection, via_guarded_find,
                        "T::unique_repeating_variant({triple:?}) diverged from the guarded-first-witness body — the guarded-first-witness identity was violated",
                    );
                }
            }
        }
        // Empty-slice endpoint: projection is `None`, guarded-find is
        // `None` via the `false`-arm short-circuit.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::unique_repeating_variant(empty),
            if <StubKind as ClosedSet>::has_unique_repeating_variant(empty) {
                <StubKind as ClosedSet>::ALL
                    .iter()
                    .copied()
                    .find(|&v| <StubKind as ClosedSet>::is_repeated_occurrence_of(v, empty))
            } else {
                None
            },
        );
    }

