    #[test]
    fn unique_repeating_variant_agrees_with_repeating_variants_singleton_across_every_triple() {
        // STRICT-REPEAT WITNESS SINGLETON IDENTITY: for every slice
        // `items`, `T::unique_repeating_variant(items) ==
        // (if T::repeating_variants(items).len() == 1 {
        // Some(T::repeating_variants(items)[0]) } else { None })` —
        // when `items` has a unique strict-repeat witness, the
        // declaration-order strict-repeat witness-collection
        // T::repeating_variants collapses to a length-1 Vec containing
        // EXACTLY that unique variant, so its slot-0 wrapped in `Some`
        // coincides with THIS projection. Independent cross-check on
        // the witness-Vec surface axis distinct from the guarded-find
        // arm.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_projection = <StubKind as ClosedSet>::unique_repeating_variant(&triple);
                    let witnesses = <StubKind as ClosedSet>::repeating_variants(&triple);
                    let via_witness_singleton = if witnesses.len() == 1 {
                        Some(witnesses[0])
                    } else {
                        None
                    };
                    assert_eq!(
                        via_projection, via_witness_singleton,
                        "T::unique_repeating_variant({triple:?}) diverged from the repeating_variants-singleton form — the strict-repeat witness singleton identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn unique_repeating_variant_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // T::has_unique_repeating_variant (ordering-agnostic) guarding
        // a declaration-order find sweep of T::ALL through
        // T::is_repeated_occurrence_of (ordering-agnostic — factored
        // through T::count_occurrences_of). The output ordering is
        // fixed by T::ALL's declaration order regardless of `items`'
        // ordering.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::unique_repeating_variant(&triple);
                    let via_reversed = <StubKind as ClosedSet>::unique_repeating_variant(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::unique_repeating_variant({triple:?}) diverged from T::unique_repeating_variant({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn assert_closed_set_well_formed_catches_always_some_first_drift_in_unique_repeating_variant() {
        // Drift catch — clause (172)'s empty-slice + full-set +
        // doubled-full-set fixpoint arms fire when an override folds
        // the set-level strict-repeat witness projection onto
        // `Some(T::first())` unconditionally. Empty-slice arm produces
        // `Some(T::ALL[0]) != None`; full-set arm at cardinality >= 2
        // produces `Some(T::ALL[0]) != None`; doubled-full-set arm at
        // cardinality >= 2 produces `Some(T::ALL[0]) != None`.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedUniqueRepeatingVariantSomeKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedUniqueRepeatingVariantSomeKind(pub String);

        impl core::fmt::Display for UnknownDriftedUniqueRepeatingVariantSomeKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted unique_repeating_variant some kind: {}",
                    self.0
                )
            }
        }

        impl DriftedUniqueRepeatingVariantSomeKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedUniqueRepeatingVariantSomeKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted unique_repeating_variant some kind";
            type Unknown = UnknownDriftedUniqueRepeatingVariantSomeKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedUniqueRepeatingVariantSomeKind(s.to_owned())
            }
            fn unique_repeating_variant(_items: &[Self]) -> Option<Self> {
                // Drift: return `Some(T::first())` regardless. Fires
                // clause (172)'s empty-slice + full-set + doubled-full-
                // set fixpoint arms at `Some(_) != None`.
                Some(Self::Alpha)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedUniqueRepeatingVariantSomeKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedUniqueRepeatingVariantSomeKind whose unique_repeating_variant override folds onto `Some(T::first())` unconditionally — clause (172)'s empty-slice + full-set + doubled-full-set fixpoint arms MUST reject the drift",
        );
    }

