    #[test]
    fn assert_closed_set_well_formed_catches_always_false_drift_in_is_unique_repeating_variant_of()
    {
        // Drift catch — clause (173)'s bimodal-triple positive arm
        // at cardinality >= 3 fires when an override folds the per-
        // target unique-strict-repeat predicate onto `false`
        // regardless of target. The fixture demands a `true` at
        // T::ALL[0], which the drifted override cannot produce.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedIsUniqueRepeatingVariantOfFalseKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedIsUniqueRepeatingVariantOfFalseKind(pub String);

        impl core::fmt::Display for UnknownDriftedIsUniqueRepeatingVariantOfFalseKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted is_unique_repeating_variant_of false kind: {}",
                    self.0
                )
            }
        }

        impl DriftedIsUniqueRepeatingVariantOfFalseKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedIsUniqueRepeatingVariantOfFalseKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted is_unique_repeating_variant_of false kind";
            type Unknown = UnknownDriftedIsUniqueRepeatingVariantOfFalseKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedIsUniqueRepeatingVariantOfFalseKind(s.to_owned())
            }
            fn is_unique_repeating_variant_of(_target: Self, _items: &[Self]) -> bool {
                // Drift: return `false` regardless. Fires clause
                // (173)'s bimodal-triple positive arm at
                // `false != true` at T::ALL[0] on the canonical
                // fixture at cardinality >= 3.
                false
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedIsUniqueRepeatingVariantOfFalseKind>();
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedIsUniqueRepeatingVariantOfFalseKind whose is_unique_repeating_variant_of override folds onto `false` unconditionally — clause (173)'s bimodal-triple positive fixpoint arm at cardinality >= 3 MUST reject the drift (the SOLE positive arm at T::ALL[0] on the canonical fixture)",
        );
    }

