    #[test]
    fn unique_unique_variant_returns_some_all_1_on_the_bimodal_triple_at_cardinality_gte_three() {
        // BIMODAL-TRIPLE CONTRACT AT CARDINALITY `>= 3`: LOAD-BEARING
        // `Some(T::ALL[1])`-arm catch DISJOINT-WITNESS mirror of
        // unique_repeating_variant which lands on `Some(T::ALL[0])`
        // on the SAME fixture one MULTIPLICITY-BAND axis over — the
        // two POSITIVE `Some(_)` corners of the equivalence-partition
        // (mult `>= 2`, mult `== 1`) uniqueness columns report
        // DIFFERENT witnesses on the same slice, pinning the two
        // multiplicity-bands as ORTHOGONAL uniqueness axes with
        // disjoint witness projections. On `[T::ALL[0], T::ALL[0],
        // T::ALL[1]]` T::ALL[0] sits at count 2 (the (mult `>= 2`)
        // witness), T::ALL[1] at count 1 (the SOLE (mult `== 1`)
        // witness), T::ALL[2..] at count 0;
        // T::count_unique_variants reports `1`,
        // T::has_unique_unique_variant returns `true`, and the
        // declaration-order find sweep of T::ALL through
        // T::is_unique_occurrence_of bypasses T::ALL[0] (count 2 !=
        // 1) and lands on T::ALL[1] at slot 1.
        assert_eq!(<StubKind as ClosedSet>::CARDINALITY, 3);
        let bimodal_triple = [
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[0],
            <StubKind as ClosedSet>::ALL[1],
        ];
        assert_eq!(
            <StubKind as ClosedSet>::unique_unique_variant(&bimodal_triple),
            Some(<StubKind as ClosedSet>::ALL[1]),
            "T::unique_unique_variant({bimodal_triple:?}) diverged from `Some(T::ALL[1])` — the LOAD-BEARING DISJOINT-WITNESS mirror of unique_repeating_variant which lands on `Some(T::ALL[0])` on the SAME fixture — the equivalence-partition (mult >= 2) and (mult == 1) `Option<Self>` uniqueness columns split on this canonical fixture with DIFFERENT positive witnesses",
        );
    }

    #[test]
    fn unique_unique_variant_equals_has_unique_unique_variant_gated_find_across_every_triple() {
        // GUARDED-FIRST-WITNESS IDENTITY: for every slice `items`,
        // `T::unique_unique_variant(items) == if
        // T::has_unique_unique_variant(items) {
        // T::ALL.iter().copied().find(|&v| T::is_unique_occurrence_of(
        // v, items)) } else { None }` — the canonical form the body
        // uses. Sweeping every length-3 triple pins the identity
        // across the full 27-corner domain.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_projection = <StubKind as ClosedSet>::unique_unique_variant(&triple);
                    let via_guarded_find =
                        if <StubKind as ClosedSet>::has_unique_unique_variant(&triple) {
                            <StubKind as ClosedSet>::ALL.iter().copied().find(|&v| {
                                <StubKind as ClosedSet>::is_unique_occurrence_of(v, &triple)
                            })
                        } else {
                            None
                        };
                    assert_eq!(
                        via_projection, via_guarded_find,
                        "T::unique_unique_variant({triple:?}) diverged from the guarded-first-witness body — the guarded-first-witness identity was violated",
                    );
                }
            }
        }
        // Empty-slice endpoint: projection is `None`, guarded-find is
        // `None` via the `false`-arm short-circuit.
        let empty: &[StubKind] = &[];
        assert_eq!(
            <StubKind as ClosedSet>::unique_unique_variant(empty),
            if <StubKind as ClosedSet>::has_unique_unique_variant(empty) {
                <StubKind as ClosedSet>::ALL
                    .iter()
                    .copied()
                    .find(|&v| <StubKind as ClosedSet>::is_unique_occurrence_of(v, empty))
            } else {
                None
            },
        );
    }

    #[test]
    fn unique_unique_variant_is_some_iff_has_unique_unique_variant_across_every_triple() {
        // IS-SOME COINCIDENCE IDENTITY: for every slice `items`,
        // `T::unique_unique_variant(items).is_some() ==
        // T::has_unique_unique_variant(items)` — the `Option<Self>`
        // return's `is_some` bit COINCIDES with the set-level unique-
        // band uniqueness bit. Independent cross-check on the surface
        // axis (`Option::is_some` vs conditional-Option construction).
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_is_some =
                        <StubKind as ClosedSet>::unique_unique_variant(&triple).is_some();
                    let via_predicate = <StubKind as ClosedSet>::has_unique_unique_variant(&triple);
                    assert_eq!(
                        via_is_some, via_predicate,
                        "T::unique_unique_variant({triple:?}).is_some() diverged from T::has_unique_unique_variant({triple:?}) — the is-some coincidence identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn unique_unique_variant_agrees_with_unique_variants_singleton_across_every_triple() {
        // UNIQUE-WITNESS SINGLETON IDENTITY: for every slice `items`,
        // `T::unique_unique_variant(items) ==
        // (if T::unique_variants(items).len() == 1 {
        // Some(T::unique_variants(items)[0]) } else { None })` —
        // when `items` has a unique singleton-multiplicity witness,
        // the declaration-order strict-uniqueness witness-collection
        // T::unique_variants collapses to a length-1 Vec containing
        // EXACTLY that unique variant, so its slot-0 wrapped in
        // `Some` coincides with THIS projection. Independent cross-
        // check on the witness-Vec surface axis distinct from the
        // guarded-find arm.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let via_projection = <StubKind as ClosedSet>::unique_unique_variant(&triple);
                    let witnesses = <StubKind as ClosedSet>::unique_variants(&triple);
                    let via_witness_singleton = if witnesses.len() == 1 {
                        Some(witnesses[0])
                    } else {
                        None
                    };
                    assert_eq!(
                        via_projection, via_witness_singleton,
                        "T::unique_unique_variant({triple:?}) diverged from the unique_variants-singleton form — the unique-witness singleton identity was violated",
                    );
                }
            }
        }
    }

    #[test]
    fn unique_unique_variant_is_invariant_under_slice_reversal_across_every_triple() {
        // REVERSAL-INVARIANCE CONTRACT: the projection factors through
        // T::has_unique_unique_variant (ordering-agnostic — the
        // underlying T::count_unique_variants is invariant under
        // slice-reversal) guarding a declaration-order find sweep of
        // T::ALL through T::is_unique_occurrence_of (ordering-agnostic
        // — factored through T::count_occurrences_of). The output
        // ordering is fixed by T::ALL's declaration order regardless
        // of `items`' ordering.
        for a in <StubKind as ClosedSet>::ALL.iter().copied() {
            for b in <StubKind as ClosedSet>::ALL.iter().copied() {
                for c in <StubKind as ClosedSet>::ALL.iter().copied() {
                    let triple = [a, b, c];
                    let reversed: Vec<StubKind> = triple.iter().rev().copied().collect();
                    let via_forward = <StubKind as ClosedSet>::unique_unique_variant(&triple);
                    let via_reversed = <StubKind as ClosedSet>::unique_unique_variant(&reversed);
                    assert_eq!(
                        via_forward, via_reversed,
                        "T::unique_unique_variant({triple:?}) diverged from T::unique_unique_variant({reversed:?}) — the reversal-invariance contract was violated",
                    );
                }
            }
        }
    }

