    #[test]
    fn is_unique_missing_variant_of_returns_true_only_at_the_absent_witness_on_the_single_missing_slice(
    ) {
        // LOAD-BEARING SINGLE-MISSING POSITIVE ARM AT CARDINALITY
        // >= 2: on the canonical fixture
        // `T::ALL[..T::CARDINALITY - 1]` the last-declaration-slot
        // variant is the SOLE absent variant, every other variant
        // sits at count 1; T::has_unique_missing_variant reports
        // `true` via count_missing == 1, `!T::occurs_in` reports
        // `true` only at T::ALL[T::CARDINALITY - 1], and the
        // conjunction lands on `true` at T::ALL[T::CARDINALITY - 1]
        // and `false` at every other target. LOAD-BEARING
        // DISCRIMINATOR from is_unique_repeating_variant_of which
        // stays UNIVERSALLY `false` on the SAME fixture (every
        // present variant sits at count 1, count_repeating_variants
        // == 0, and the strict-repeat uniqueness bit falsifies).
        assert!(<StubKind as ClosedSet>::CARDINALITY >= 2);
        let single_missing: Vec<StubKind> = <StubKind as ClosedSet>::ALL
            [..<StubKind as ClosedSet>::CARDINALITY - 1]
            .iter()
            .copied()
            .collect();
        let expected_positive_slot = <StubKind as ClosedSet>::CARDINALITY - 1;
        for (slot, v) in <StubKind as ClosedSet>::ALL.iter().copied().enumerate() {
            let expected = slot == expected_positive_slot;
            assert_eq!(
                <StubKind as ClosedSet>::is_unique_missing_variant_of(v, &single_missing),
                expected,
                "T::is_unique_missing_variant_of({v:?}, {single_missing:?}) diverged from expected == {expected} — the SOLE positive arm sits at T::ALL[T::CARDINALITY - 1] via the LOAD-BEARING miss-band unique-tie corner",
            );
        }
    }

