    fn is_unique_unique_variant_of_returns_false_on_the_non_matching_singleton_across_every_target_pair(
    ) {
        // NON-MATCHING-SINGLETON CONTRACT AT CARDINALITY >= 2:
        // T::is_unique_unique_variant_of(v, &[w]) is `false` for every
        // target v and slice-element w with T::index_of(v) !=
        // T::index_of(w) — the singleton pins w at count 1 and every
        // non-w (including v) at count 0; T::is_unique_occurrence_of
        // falsifies at v (count 0 != 1), and the conjunction collapses
        // to `false` through the membership arm.
        for v in <StubKind as ClosedSet>::ALL.iter().copied() {
            for w in <StubKind as ClosedSet>::ALL.iter().copied() {
                if <StubKind as ClosedSet>::index_of(v) != <StubKind as ClosedSet>::index_of(w) {
                    let singleton = [w];
                    assert!(
                        !<StubKind as ClosedSet>::is_unique_unique_variant_of(v, &singleton),
                        "T::is_unique_unique_variant_of({v:?}, [{w:?}]) diverged from the non-matching-singleton fixpoint `false`",
                    );
                }
            }
        }
    }

