    #[test]
    fn assert_closed_set_well_formed_catches_always_some_first_drift_in_sorted_unique_bimodal_variant(
    ) {
        // Drift catch — clause (187)'s empty-slice + flat-histogram +
        // matching-singleton + bimodal-triple fixpoint arms fire when
        // an override folds the LEX-ORDER set-level unique-bimodal-
        // variant witness onto `Some(T::first())` unconditionally. On
        // the empty slice T::sorted_unique_bimodal_variant MUST return
        // None (has_unique_bimodal_variant is false); on every non-
        // empty fixture at cardinality >= 2 the same None-arm holds.
        // An always-Some(first) override bifurcates every arm at
        // `Some(_) != None`.
        //
        // Note: no `always-None` drift-catch peer is possible on a
        // cardinality-3 stub — at T::CARDINALITY >= 2 the correct
        // sorted-unique-bimodal-witness answer is `None` on EVERY
        // canonical fixture (the degenerate-closer property inherited
        // from clause (167) via clause (187)'s ordering-choice-
        // irrelevance identity), so an always-None override matches
        // truth structurally on the multi-variant stub. The structural
        // catch for `None`-drifting overrides sits at T::CARDINALITY
        // == 1 in clause (187)'s guarded-lift arm on the full-set +
        // doubled-full-set fixpoints, out of reach of a multi-variant
        // stub.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        enum DriftedSortedUniqueBimodalVariantSomeFirstKind {
            Alpha,
            Beta,
            Gamma,
        }

        #[derive(Debug, PartialEq, Eq)]
        struct UnknownDriftedSortedUniqueBimodalVariantSomeFirstKind(pub String);

        impl core::fmt::Display for UnknownDriftedSortedUniqueBimodalVariantSomeFirstKind {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                write!(
                    f,
                    "unknown drifted sorted_unique_bimodal_variant some-first kind: {}",
                    self.0
                )
            }
        }

        impl DriftedSortedUniqueBimodalVariantSomeFirstKind {
            const ALL: [Self; 3] = [Self::Alpha, Self::Beta, Self::Gamma];
        }

        impl ClosedSet for DriftedSortedUniqueBimodalVariantSomeFirstKind {
            const ALL: &'static [Self] = &Self::ALL;
            const SET_LABEL: &'static str = "drifted sorted_unique_bimodal_variant some-first kind";
            type Unknown = UnknownDriftedSortedUniqueBimodalVariantSomeFirstKind;
            fn label(self) -> &'static str {
                match self {
                    Self::Alpha => "alpha",
                    Self::Beta => "beta",
                    Self::Gamma => "gamma",
                }
            }
            fn make_unknown(s: &str) -> Self::Unknown {
                UnknownDriftedSortedUniqueBimodalVariantSomeFirstKind(s.to_owned())
            }
            fn sorted_unique_bimodal_variant(_items: &[Self]) -> Option<Self> {
                // Drift: always return Some(first). Fires clause
                // (187)'s empty-slice arm (Some(_) != None) AND every
                // non-empty fixpoint arm at cardinality >= 2
                // (Some(_) != None).
                Some(Self::Alpha)
            }
        }

        let result = std::panic::catch_unwind(|| {
            super::assert_closed_set_well_formed::<DriftedSortedUniqueBimodalVariantSomeFirstKind>(
            );
        });
        assert!(
            result.is_err(),
            "assert_closed_set_well_formed accepted a DriftedSortedUniqueBimodalVariantSomeFirstKind whose sorted_unique_bimodal_variant override folds onto Some(first) unconditionally — clause (187)'s empty-slice + flat-histogram + matching-singleton + bimodal-triple fixpoint arms MUST reject the drift",
        );
    }

